    },
    ['Aht Urhgan Mission 16'] = {
        title        = 'Ghosts of the Past',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have uncovered the truth behind the Ashu Talif and its ghostly crew. Report your findings to President Naja.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Back at Aht Urhgan Whitegate, speak to Naja Salaheem for a cutscene.' },
        },
    },
    ['Aht Urhgan Mission 17'] = {
        title        = 'Guests of the Empire',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Ovjang\'s Errand Runner',
        repeatable   = 'No',
        description  = 'You have received an invitation to the palace from the Grand Vizier. President Naja has offered to help you find appropriate clothing for the occasion.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Speak to Naja Salaheem for a cutscene.' },
            { 'Play dress up with Naja Salaheem.' },
            { 'Before you can continue, Naja Salaheem will ask that you wear something more appropriate to the palace.' },
            { 'Make sure to speak with her again after playing dress up with her and wearing the armor listed below otherwise you won\'t get the CS at the palace.', sub = {
                { 'In addition to the listed armor, you must also be wearing gloves, leg armor, and boots. They do not however, have to match anything else you are wearing.', sub = {
                    { 'Gear that prevents the player from equipping gear in another slot (sometimes referred to as "occupying multiple slots" or "multi-slot gear") does not count as wearing gear in the prohibited slots.' },
                } },
                { 'Wearing the following armors are known to allow you to continue. Hover a name to see the job level requirements, and click on the image to check the Auction House stock (Be sure to set your server on the top left of FFXIAH.com if you haven\'t):', sub = {
                    { 'Adaman Cuirass Find on FFXIAH' },
                    { 'Aketon Find on FFXIAH' },
                    { 'Amir Korazin Find on FFXIAH' },
                    { 'Arhat\'s Gi Find on FFXIAH' },
                    { 'Barone Corazza Find on FFXIAH' },
                    { 'Black Cloak Find on FFXIAH' },
                    { 'Black Cotehardie Find on FFXIAH' },
                    { 'Blessed Bliaut Find on FFXIAH' },
                    { 'Bloody Aketon Find on FFXIAH' },
                    { 'Blue Cotehardie Find on FFXIAH' },
                    { 'Byrnie Find on FFXIAH' },
                    { 'Brigandine Find on FFXIAH', sub = {
                        { 'Can be obtained for free via RoE - Conflict: Beadeaux' },
                    } },
                    { 'Cardinal Vest Find on FFXIAH' },
                    { 'Chasuble Find on FFXIAH' },
                    { 'Dusk Jerkin Find on FFXIAH' },
                    { 'Dragon Harness Find on FFXIAH' },
                    { 'Errant Houppelande Find on FFXIAH' },
                    { 'Hachiman Domaru Find on FFXIAH' },
                    { 'Haubergeon Find on FFXIAH' },
                    { 'Hauberk Find on FFXIAH' },
                    { 'Holy Breastplate Find on FFXIAH' },
                    { 'Homam Corazza Find on FFXIAH' },
                    { 'Igqira Weskit Find on FFXIAH' },
                    { 'Jaridah Peti Find on FFXIAH' },
                    { 'Justaucorps Find on FFXIAH' },
                    { 'Nashira Manteel Find on FFXIAH', sub = {
                        { 'May be bought from the Curio Vendor Moogle for 10,000 gil, if you have "Rhapsody in White".' },
                    } },
                    { 'Noble\'s Tunic Find on FFXIAH' },
                    { 'Pahluwan Khazagand Find on FFXIAH' },
                    { 'Plastron Find on FFXIAH' },
                    { 'Rasetsu Samue Find on FFXIAH' },
                    { 'Scorpion Harness Find on FFXIAH' },
                    { 'Sipahi Jawshan Find on FFXIAH' },
                    { 'Sha\'ir Manteel Find on FFXIAH' },
                    { 'Vermillion Cloak Find on FFXIAH' },
                    { 'Yigit Gomlek Find on FFXIAH' },
                } },
            } },
            { 'Check the Imperial Whitegate door at (L-8) in Aht Urhgan Whitegate with the proper attire and your weapons removed for a cutscene, after which you will receive an Imperial Mythril Piece.', sub = {
                { 'Note: Confirm that you have space in your inventory before watching the cutscene, or you\'ll have to make space and watch the entire scene again if you do not obtain your reward.' },
            } },
        },
    },
    ['Aht Urhgan Mission 18'] = {
        title        = 'Passing Glory',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Your reward from the Empress has been confiscated by President Naja. Earn the right to wear it by becoming the best mercenary you can be.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
