        },
    },
    ['Aht Urhgan Mission 19'] = {
        title        = 'Sweets for the Soul',
        starting_npc = 'Aht Urhgan Whitegate - (K-12)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Ambassador Karababa has arrived from the Federation of Windurst. The planned festivities turn into a puppet rivalry, and the insulted ambassador bypasses the palace in favor of a visit to the Shararat Teahouse.',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter the Shararat Teahouse in Aht Urhgan Whitegate for a cutscene.' },
        },
    },
    ['Aht Urhgan Mission 20'] = {
        title        = 'Teahouse Tumult',
        starting_npc = 'Aht Urhgan Whitegate - (K-11)',
        subtitle     = 'Karababa\'s Tour Guide',
        repeatable   = 'No',
        description  = 'You have been asked to guide Lady Karababa to the Olduum ruins found in the tunnels of the Aydeewa Subterrane. How will Naja react to your freelancing? And what are Aphmau and friends planning...?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Aydeewa Subterrane via one of the routes below.', sub = {
                { 'Via Wajaom Woodlands - Head to (G-7) in Wajaom Woodlands.' },
                { 'Survival Guide - Take the guide to Aydeewa Subterrane.' },
                { 'Unity Warp - Take the CL135 Wajaom Woodlands or CL145 Aydeewa Subterrane warp.', sub = {
                    { 'The entrance is directly behind you if you took the CL135 warp.' },
                } },
            } },
            { 'After the cutscene, continue further into the Subterrane until you find a room with two exits at (E-9/F-9) in the southwest part of this map.', sub = {
                { 'Monsters in this part of the Subterrane are 70+ and will aggro, so be sure you have Sneak and Invisible on.' },
            } },
            { 'Head west down the ramp which takes you to the western portion of Aydeewa Subterrane (Map 5).' },
            { 'At (F-8/G-8) there is a blank target you need to check for a cutscene.' },
            { 'The mission is finished once you watch the cutscene.' },
        },
    },
    ['Aht Urhgan Mission 21'] = {
        title        = 'Finders Keepers',
        starting_npc = 'Aydeewa Subterrane',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'After snatching the Olduum artifact, Lady Karababa has left for Salaheem\'s Sentinels. What business could she possibly have with a mercenary company?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Salaheem\'s Sentinels for a cutscene.' },
        },
    },
    ['Aht Urhgan Mission 22'] = {
        title        = 'Shield of Diplomacy',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Karababa\'s Bodyguard',
        repeatable   = 'No',
        description  = 'You are once again in the employ of Lady Karababa. This time, your role is to protect the ambassador within the ominous Navukgo Execution Chamber. Will you be able to redeem your reputation with President Naja...?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Travel to Navukgo Execution Chamber.', sub = {
                { 'The Mount Zhayolm Home Point will take you right outside the zone. (Use Unity Warp > 135 > Mount Zhayolm if you do not have the Home Point)', sub = {
                    { 'The Unity Warp will place you a short walk away from the zone. After arriving in Mount Zhayolm, immediately turn around. Head forward, then take the East junction at the (C-7)/(C-8) line. You can use your Map to locate the Home Point quickly.' },
                } },
            } },
            { 'You will get a cutscene when you first enter Navukgo Execution Chamber.' },
            { 'Examine the Decorative Bronze Gate for another cutscene.' },
            { 'Examine the gate once more to enter a battlefield.' },
            { 'The fight is against Khimaira 13.' },
            { 'Khimaira 13 uses the following special attacks:', sub = {
                { 'Dreadstorm: AoE DMG + terrorize. Removes Utsusemi.' },
                { 'Tenebrous Mist: TP is reset to 0.' },
                { 'Thunderstrike: AoE DMG + Stun. Removes Utsusemi.' },
                { 'Tourbillion: AoE DMG + Knockback. Removes Utsusemi.' },
            } },
            { 'Lady Karababa will assist you in this fight.', sub = {
                { 'She uses various high level spells and casts them much faster than players can. She seems to prefer Ancient Magic II spells.' },
                { 'If her health drops too low and she has not been healed, she will Warp from the battlefield resulting in a loss.' },
            } },
        },
    },
    ['Aht Urhgan Mission 23'] = {
        title        = 'Social Graces',
        starting_npc = 'Navukgo Execution Chamber',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You have successfully protected Lady Karababa from harm and earned high praise. Perhaps you can expect a bonus from the president when you return to Salaheem\'s Sentinels...?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Salaheem\'s Sentinels for a cutscene.' },
        },
    },
    ['Aht Urhgan Mission 24'] = {
        title        = 'Foiled Ambition',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Karababa\'s Secret Agent',
        repeatable   = 'No',
        description  = 'You have been caught in a conflict between Lady Karababa and President Naja. Probably best if you let President Naja cool down for a while...',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Salaheem\'s Sentinels again after zoning and one game day has passed.' },
        },
    },
    ['Aht Urhgan Mission 25'] = {
        title        = 'Playing the Part',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'None',
