    ['Aht Urhgan Mission 29'] = {
        title        = 'Puppet in Peril',
        starting_npc = 'Aht Urhgan Whitegate - (J-7)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'You are to escort Aphmau to Mamook on her mission to recover Ovjang. Will you find the automaton in the land of the savage Mamool Ja?',
        series       = 'Treasures of Aht Urhgan',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'After the last mission\'s cutscene is over, you will need to head to Jade Sepulcher.', sub = {
                { 'It is recommended that you use Homepoint #1 to Bhaflau Thickets.' },
                { 'If you don\'t have the Homepoint, go to Mamool Ja Staging Point. Once you take the staging point, head north to the Jade Sepulcher zoneline located at (I-9).', sub = {
                    { 'You will need both Sneak and Invisible (Status). (Or a mount)' },
