    ['Aht Urhgan Mission 33'] = {
        title        = 'Sentinels\' Honor',
        starting_npc = 'Naja Salaheem, Aht Urhgan Whitegate - (I-10)',
        subtitle     = 'Salaheem\'s Risk Assessor',
        repeatable   = 'No',
        description  = 'A villain by the name of "Duzaf the Blackheart" is rumored to have made an attempt on the life of the Empress. President Naja has vowed to claim the bounty on his head in the name of Salaheem\'s Sentinels.',
        series       = 'Treasures of Aht Urhgan',
