    ['Fork in the Road'] = {
        title        = 'Fork in the Road',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The future that was, and the future that might have been... In revisiting the paths you walked hand in hand with Lilisette and Cait Sith, you will acquire the power needed to fulfill the will of the Goddess.',
        series       = 'Wings of the Goddess',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Key Item Ronfaure dawndrop: automatically obtained at the start of this Mission.' },
            { 'Key Item Jugner dawndrop: examine the Blank Target in Jugner Forest (S) at (I-6).', sub = {
                { 'Survival Guide to East Ronfaure (S), then head east across the bridge in Jugner Forest (S), is the fastest way. It\'s nearby the Elegant Footprints from an earlier mission on the eastern side of the river.' },
            } },
            { 'Key Item La Vaule dawndrop: examine the Blank Target in La Vaule (S) at (K-9), lower right of the grid next to a house.', sub = {
                { 'You can access La Vaule (S) from (G-11) in Jugner Forest (S); there is a Survival Guide in Jugner Forest (S) right near the entrance.' },
            } },
            { 'Key Item San d\'Oria dawndrop: examine the Blank Target in Southern San d\'Oria (S) at (K-6).', sub = {
                { 'Near the Lion Springs Tavern.' },
            } },
            { 'Key Item Beaucedine dawndrop: examine the Blank Target in Beaucedine Glacier (S) at (H-9).', sub = {
                { 'Down the ramp from the Regal Pawprints near the Campaign warp at (H-8).' },
            } },
            { 'Key Item Xarcabard dawndrop: examine the Blank Target in Xarcabard (S) HP #1 at (F-8).', sub = {
                { 'Next to Rally Point: Red.' },
            } },
            { 'Key Item Throne Room dawndrop: examine the Blank Target in Throne Room (S) (Castle Zvahl Keep [S], HP #1)', sub = {
                { 'Middle of walkway, west side.' },
            } },
            { 'Key Item Walk of Echoes dawndrop: It is best to do this one last, as the next mission is at Walk of Echoes. Examine the Blank Target in Walk of Echoes south of the conflux.', sub = {
                { 'The C.A (Campaign Arbiter) Warp Grauberg (S) will bring you closest to reach the Witchfire Glen Veridical Conflux at (F-5) for this objective if you have little to no progress with Voidwatch.' },
                { 'Use the Survival Guide to teleport to Pashhow Marshlands (S) and use the Veridical Conflux at (J-9) to enter and head east then south (This option does require progression through Voidwatch expansion).' },
                { 'OR, enter from Grauberg (S) at (F-5) then head south.' },
                { 'OR, if you have obtained the Key Item Lightsworm, you may use any blue ??? near the Cavernous Maws surrounding Jeuno (past or present) to zone into Walk of Echoes, then head south to the Blank Target. May not work if you are on Somber Dreams.' },
            } },
        },
    },
