    ['In the Name of the Father'] = {
        title        = 'In the Name of the Father',
        starting_npc = 'La Vaule (S)',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'More motivated than ever, Lilisette continues to pursue Cait Sith, now in hopes of saving her father from a seemingly unavoidable end. To lure the regal feline, aid her in relieving the tears shed in the name of the Crystal War.',
