    ['Crystalline Mission 10'] = {
        title        = 'Banishing the Echo',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'To reach your final destination, you must recover the twelve remaining fragments of the mysterious crystal...',
        series       = 'A Crystalline Prophecy',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'During this mission, you will have to examine Seed Fragments in each zone to receive a level cap status (level 30). While under the effects of this level cap, you will be able to collect key items by touching Seed Afterglows. You will not be able to be cured by people who are not under the level cap status, but you will also not lose Experience Points should you die.', sub = {
                { 'Trust Magic is not available during this level restriction effect.' },
            } },
            { 'Prism Powders and Silent Oils are recommended if you solo this, as there can be monsters that aggro by magic around such as dolls and elementals. Seed Fragments tend to be surrounded by monsters that aggro by sight in most cases, so you\'ll want to drop your invisibility next to the Seed Fragment as soon as they are all facing away from you, examine it, and become invisible again as quickly as possible.' },
        },
    },
    ['Crystalline Mission 11'] = {
