    ['Crystalline Mission 4'] = {
        title        = 'Gatherer of Light (II)',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Was it all truly decided before the dawn of time...? When the crystal sends forth its dark minions, only you can put a stop to them!',
