    ['Seekers of Adoulin Mission 4-2'] = {
        title        = 'Lighting the Way',
        starting_npc = 'N/A',
        subtitle     = 'Knower of Untruths',
        repeatable   = 'No',
        description  = 'Mission Orders: Arciela is certain that Ortharsyne has shown her the way, and that it leads to the summit of Mount Kamihr. Find the path amidst the snowbanks in Kamihr Drifts so that you two can climb the mountain.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Alpine Trail in Kamihr Drifts at (H-5) for a cutscene. This will take you into a zone named Mount Kamihr.', sub = {
                { 'This is the very northern-middle point on the map.', sub = {
                    { 'The fastest way there is take Bivouac #3, go into the northern tunnel and follow the left wall heading north.' },
                    { 'Alternatively, the Home Point is also nearby' },
                } },
            } },
        },
    },
    ['Seekers of Adoulin Mission 4-2-1'] = {
        title        = 'Sajj\'aka',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Awaiting you at the peak of Mount Kamihr was Sajj\'aka, a serpent with a reputation for heralding realm-wide upheaval and a stubborn demeanor. Head back to Adoulin to research more on Ulbukan history so that he will be more receptive.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Celennia Memorial Library for a cutscene.' },
            { 'Read the different stories in the cutscene to continue.' },
        },
    },
    ['Seekers of Adoulin Mission 4-2-2'] = {
        title        = 'Studying Up',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have learned all you can at Celennia Memorial Library. Return to Mount Kamihr and seek another audience with Sajj\'aka.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Return to the Alpine Trail in Kamihr Drifts at (H-5), north of Bivouac #3, for a cutscene.' },
            { 'You must answer the questions correctly to proceed. Yorcia Weald Morimar The Serpentine Labyrinth. Yes it does. Who are "They"? Unleash a feral scream. What are you proposing?', sub = {
                { 'The answers to the questions are:' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 4-2-3'] = {
        title        = 'A Vow of Truth',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Sajj\'aka has revealed that the doors to the labyrinth are beginning to open, and Hades\' revival is imminent. Unless Sajj\'aka returns to fighting form, there is no chance of staving off these sinister forces. Yet where could the holy dragon\'s scales be...?',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Woh Gates from any entrance for a cutscene.', sub = {
                { 'The Frontier Station in Kamihr Drifts is the closest from this zone, the entrance is at (K-11).' },
                { 'If you\'re coming from the city, the closest waypoint is Marjami Ravine WP #4, and a short walk to the northwest.' },
            } },
        },
    },
    ['Seekers of Adoulin Mission 4-2-4'] = {
        title        = 'Darrcuiln',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have once again met with Darrcuiln, this time in Woh Gates. Follow his lead.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the spot Darkened Crevice in Woh Gates at the (G-7)/(G-8) border for a cutscene. It is slightly inside a tunnel, just before the downward slope.', sub = {
                { 'If you\'re coming from the Kamihr Drifts entrance, fall down at (I-5) then fall down again at (H-6), and once you\'re in the big room proceed to the (G-7)/(G-8) border.' },
                { 'If you\'re coming from the Marjami Ravine entrance, follow the left wall the whole way, which will let you skip the Colonization Reive at (H-9), though you\'ll still need to participate in one at (H-7) to clear the way.', sub = {
                    { 'Before getting too close to the big room from either route, use Sneak+Invisible at a distance (or better yet use Silent Oil & Prism Powder), as the Bergschrund Gefryst is aggressive toward magic, Metalcruncher Worm is aggressive to sound, and Serac Rabbit and Powdery Snoll are aggressive to sight.' },
                } },
            } },
            { 'You will receive the Key Item Tuft of golden fur after this cutscene. This is considered a BCNM entry item, and will be lost upon entry to the upcoming battle.' },
        },
    },
    ['Seekers of Adoulin Mission 4-3'] = {
        title        = 'The Gates',
        starting_npc = 'N/A',
        subtitle     = 'Ulbukan Understudy',
        repeatable   = 'No',
        description  = 'Mission Orders: Chasing after Darrcuiln, you stumbled upon hordes of umbrils fighting leafkins. Who is the strange man fighting alongside the woodland creatures? Assist them in battle and find out the truth.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Darkened Crevice at (G-8) in Woh Gates to enter "The Gates" BCNM against waves of Umbrils.', sub = {
                { 'You may attempt the Battlefield solo.' },
                { 'The battle starts automatically after about a minute. Giving you a quick moment to buff and call Trusts.' },
            } },
            { 'You are assisted by Arciela, Darrcuiln, Noble Warrior, and some cute Resolute Leafkins.', sub = {
                { 'Arciela Casts Haste, Protect V, and Shell V on herself, party members, and the other NPCs.' },
            } },
            { 'The fight is lost if any NPCs die.', sub = {
                { 'The NPCs can be buffed and healed with Blood Pact: Wards.' },
                { 'NPCs can also be buffed via accession if you cast it on a trust you summon, such as Regen V.' },
                { 'Curaga when cast on a Trust will affect the entire group, but not when cast on a PC.' },
            } },
            { 'The fight is still won if all players are dead, but the NPCs finish killing the monsters.' },
            { 'See the Discussion Page page for strategies and further battle information.' },
        },
    },
    ['Seekers of Adoulin Mission 4-3-1'] = {
        title        = 'Morimar',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The man calls himself Morimar--one of the generals who fought alongside the founder king. He has an inkling as to where Sajj\'aka\'s scales may lie. Return to Mount Kamihr with him and seek yet another audience.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Return to Kamihr Drifts and examine the Alpine Trail at (H-5), north of Bivouac #3, once again.' },
        },
    },
    ['Seekers of Adoulin Mission 4-3-2'] = {
        title        = 'A New Force Arises',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Morimar proffers that Sajj\'aka\'s scales have been sealed deep within the labyrinth. Employ The holy dragon\'s protection to access areas of Ra\'Kaznar previously sealed off, and find his scales.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Outer Ra\'Kaznar by using the Liseran Door: Entrance in Kamihr Drifts (F-8).', sub = {
                { 'If previously unlocked, you can use the Waypoint: Enigmatic Device → Outer Ra\'Kaznar.' },
            } },
            { 'In Outer Ra\'Kaznar, find and examine the following location:', sub = {
                { 'Effigy of Sealing at (I-11) (Upstairs, Map 1) to receive the Key Item Starblessed scale.' },
                { 'Silvery Plate at (C-7) (Upstairs, Map 1) to receive the Key Item Silvery plate.', sub = {
                    { 'Note: Do not proceed to next scale before picking up this Key Item. It allows use of the elevator at (I-6) (Upstairs, Map 1) to reach last scale.' },
                } },
                { 'Effigy of Sealing at (H-2) (Upstairs, Map 1) to receive the Key Item Moontouched scale.' },
                { 'Demonic Architrave at (C-8) (Basement, Map 2) to receive the Key Item Sunkissed scale.', sub = {
                    { 'While the scales can be collected in any order, it is highly recommended to use the order provided above due to the natural flow of traversing throughout the zone.' },
                    { '(Optional): After collecting any scale, minor additional cutscenes become available at both the Alpine Trail at (H-5) in Kamihr Drifts and the Celennia Memorial Library. Even if they are not triggered by returning halfway through the Mission, they can still be watched at the Goblin Footprint at (K-11) in Kamihr Drifts and by talking to Jedelaih in the Celennia Memorial Library respectively.', sub = {
                        { 'There are no additional scenes for having collected two scales.' },
                    } },
                } },
            } },
            { 'After collecting all the items, return to Kamihr Drifts - Biovauc #3 (or Home Point) again and examine the Alpine Trail at (H-5) for a cutscene and the Key Item World Tree sapling.' },
        },
    },
    ['Seekers of Adoulin Mission 4-3-3'] = {
        title        = 'The Sacred Sapling',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Sajj\'aka has provided you with a sapling that can be used to heal the World Tree by utilizing its roots. But how...? The only way is to ask the World Tree itself...and the answer may lie in Castle Adoulin.',
        series       = 'Seekers of Adoulin',
