    },
    ['Seekers of Adoulin Mission 5-1-1'] = {
        title        = 'Arciela\'s Missive',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though Ploh Trishbahk shooed you away from the castle gates, she secretly provided you with a note from Arciela. Perhaps you should take a look at it.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to your Temporary Key Items and read the Key Item Hastily scribbled note.', sub = {
                { 'It is located before your Phantom Gem Key Items, just after the not-so-temporary Pristine hair ribbon.' },
                { 'Performing this step is required. You must actually do this in order to continue.' },
            } },
            { 'Go to the Waterfront in Western Adoulin, Waypoint #9 and examine the Sunrise Beacon (J-4) at the north end of the dock for a cutscene.', sub = {
                { 'If you have not opened the Key Item Hastily scribbled note in your Temporary Key Items, examining the Sunrise Beacon will produce the message "There is nothing out of the ordinary here."' },
