        },
    },
    ['Seekers of Adoulin Mission 5-1-2'] = {
        title        = 'Heroes, Unite!',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Arciela postulates that the other two members of the Xol Triumvirate have resurrected. Find the ancient heroes who once struggled against them.',
        series       = 'Seekers of Adoulin',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Kamihr Drifts (Bivouac #3 or Home Point #1 are quickest) and examine the Alpine Trail at (H-5) for a cutscene.' },
