    ['Rhapsodies of Vanadiel Mission 1-12'] = {
        title        = 'Fate\'s Call',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Lion has seen another vision. The orb you have received must be filled with sufficient light to stop the encroaching darkness. Vanquish the Shadow Lord before the reckoning comes. If you have already done so, report to Gilgamesh in Norg.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
