    ['Rhapsodies of Vanadiel Mission 1-13'] = {
        title        = 'What Lies Beyond',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The visions do not cease, with Iroha\'s voice emanating from the orb. Head to Norg.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Norg.', sub = {
                { 'If you have not yet started Rise of the Zilart Missions, then the cutscene for Rise of the Zilart Mission 1 (The New Frontier) will play.' },
