    ['Rhapsodies of Vanadiel Mission 1-14'] = {
        title        = 'The Ties that Bind',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ill tidings abound. Something is causing sailors to take leave of their senses, with a strange ringing reminding you of what occurred in Escha - Zi\'Tah. See what is happening in Sea Serpent Grotto.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Exit Norg on foot (not chocobo!) to the South (H-10).' },
            { 'You\'re now on Map 1 at (F-1) of Sea Serpent Grotto. Keep following the tunnel southward until you get to an apparent dead end near a torch at (H-6).' },
            { 'There\'s a hidden door here that has a blank label when you target it, and will open it when you interact with it. It\'s always unlocked - open it and proceed.', sub = {
                { '(This is usually the entrance you\'d need to find when getting into Norg traditionally.)' },
            } },
            { 'From here, take an immediate left to go north-east to J-5, and then a right (southward) to the one-way drop down at K-7. Continue!' },
            { 'Now hug the left wall as you go forward, ignoring the Ornamented Door\' (J-10) and proceeding down the tunnel to the left, until you reach a large room (K-11).' },
            { 'The sparkling ??? is right in front of you on the edge of the water (J-12).' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-15'] = {
        title        = 'Impurity',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The great Siren is the cause of the recent disturbances plaguing Norg, and she claims that Iroha was not the only one who came to the present time from the future. The masked man attacked Iroha, who faded into nothingness. Chase after him.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'If you are still in Sea Serpent Grotto from the previous quest, a Black Mage can cast Escape to take themselves and their party straight out to Yuhtunga Jungle.', sub = {
                { 'Players without the spell Escape can instead take a short walk to the exit.' },
            } },
            { 'If you are starting from Norg, the quickest means to reach the ??? is renting a Chocobo from Marilleune (H-9) in Norg, near the exit to Sea Serpent Grotto and ride to the ???.' },
            { 'If you are starting from any other location, an alternative quick trip is using the Level 119 Unity Wanted teleport to Yuhtunga Jungle.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-16'] = {
        title        = 'The Lost Avatar',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Siren and the masked man attempted to conjure forth another vortex in Yuhtunga Jungle in a bid to cause Escha to spread further. Fight the winged beast and stop her before it\'s too late.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Note that the following fight is considerably more difficult than the content leading up to it. If solo (with trusts), you may want to reach at least level 80 before attempting.' },
            { 'Examine the ??? again to start a battle.', sub = {
                { 'You will be fighting Siren.' },
                { 'Siren will despawn after approximately 15 minutes, ending the fight. You will need to kill her within 15 minutes to receive credit.' },
                { 'Can Charm, which will despawn your trusts if it hits you. Charm has no effect if it hits your trusts, so let one of them tank her. (Item Level 119 players should have no issues soloing her even if they do get charmed.)' },
                { 'Uses Massacre Elegy and Wind Threnody II.' },
                { 'Absorbs Wind Elemental damage, including that from Skillchains such as Detonation or Fragmentation.', sub = {
                    { 'Take care when using Trusts such as Cipher: Shantotto II, as their AI is designed to target the foe\'s greatest Elemental weakness, however in cases where foes will completely Absorb an Element, the AI will instead target that element to heal the foe.' },
                } },
            } },
            { 'After the fight, examine the ??? again for another cutscene.', sub = {
                { 'You will be rewarded with Key Item "Rhapsody in Azure".' },
                { 'If you "Call for Help" on Siren, you won\'t get the cutscene and will have to wait 1 minute to pop again.' },
                { 'In the event of death, one may rezone and still receive the cutscene as long as Siren is defeated.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-17'] = {
        title        = 'Volto Oscuro',
        starting_npc = 'N/A',
        subtitle     = 'The Fated',
        repeatable   = 'No',
        description  = 'Mission Orders: Siren has regained her senses and shared with you what the future holds. Volto Oscuro\'s power is immense, and it will stop at nothing to fulfill its goals. Report what you learned to Gilgamesh back in Norg.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Norg and examine Gilgamesh\'s Oaken Door for another cutscene.', sub = {
                { 'You will be given a Cipher: Zeid II.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-18'] = {
        title        = 'Ring My Bell',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh and his compatriot have decided to search for a man from the Far East by the name of Tenzen. Explore Escha - Zi\'Tah while they look for clues.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'To start the next chapter, examine Gilgamesh\'s door in Norg multiple times, then go in and talk to Gilgamesh. This will start a cutscene with Gilgamesh, Aldo, Tenzen, Zeid, Kagero, and Prishe. Once the custscene\'s are completed, you will see the next chapter flagged.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-2'] = {
        title        = 'Resonance',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A cryptic vision from the crystal has played in your mind. A strange woman bathed in light descended from the mothercrystal in search of someone. What is the land of which she spoke? Perhaps someone in Selbina or Mhaura could provide clues.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into either Selbina or Mhaura', sub = {
                { 'Note: This will change what you have to do for the next mission.', sub = {
                    { 'This is not important as it just determines which Crag you will farm the item around. Either Konschtat or Tahrongi.' },
                } },
            } },
            { 'After the cutscene you will now be on the next mission.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-3'] = {
        title        = 'Emissary from the Seas',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have been encouraged to meet the town\'s leader. Make haste.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'If you picked the Selbina path:', sub = {
                { 'Talk to Naillina at (F-9) in the Mayor\'s Residence.' },
                { 'Choose the first dialogue option: "You wanted an adventurer?"' },
            } },
            { 'If you picked the Mhaura path:', sub = {
                { 'Talk to Numi Adaligo at (F-9) in the Governor\'s House.' },
                { 'Choose the first dialogue option: "You\'re searching for adventurers?"' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-4'] = {
        title        = 'Set Free',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The town\'s leader has informed you that Gilgamesh is looking for a particular adventurer and that he wants some goods. Mhaura: three Mandragora Dewdrops from pygmaioi. Selbina: three clumps of bee pollen from huge wasps.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Purchase from the Auction House or farm 3x Bee Pollen from Huge Wasps in La Theine Plateau or Konschtat Highlands.', sub = {
                { 'If you choose to farm the Pollen, the best area is in Konschtat Highlands around the Crag of Dem. There are about 12-15 spawns that you will find as you run around the Crag, and by the time you make a lap they will have respawned.' },
                { 'In La Theine Plateau, the spawns are spread out with only 3-4 at each of the valleys.' },
                { 'Be sure to use Wide Scan under your Map menu to help find the Huge Wasps.' },
            } },
            { 'Return to Selbina and trade the pollen to Abelard.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-5'] = {
        title        = 'The Beginning',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh claims that he chanced upon a young woman while sailing the stormy western seas, and wants you to meet her in Norg. Speak to his crew when you are ready to leave, but those with Gilgamesh\'s letter of introduction should use it first.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'For Selbina path:', sub = {
                { 'Talk to Pacomart at (H-10) in Selbina to be brought to Norg.', sub = {
                    { 'If for some reason you do not complete the next step, he will take you back to Norg again.' },
                } },
                { 'Talk to the Oaken Door at (K-8) in Norg to Gilgamesh\'s room.' },
            } },
            { 'For Mhaura path:', sub = {
                { 'Talk to Tonasav at (H-9) in Mhaura to be brought to Norg.', sub = {
                    { 'If for some reason you do not complete the next step, he will take you back to Norg again.' },
                } },
                { 'Talk to the Oaken Door at (K-8) in Norg to Gilgamesh\'s room.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-6'] = {
        title        = 'Flames of Prayer',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have met Iroha, a priestess of Reisenjima Sanctorium. She has somehow descended from the future, and claims that the world will be consumed if it continues on its current path. Yet she vanished without a trace--ask Gilgamesh what to do next.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'This is a second time after the previous mission.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-7'] = {
        title        = 'The Path Untraveled',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh\'s daughter, Lion, may be able to find something out. Complete your home nation\'s mission up through rank 2 first. If you already have, follow the orb\'s guidance and seek her out by the Crag of Holla, Dem, or Mea.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Shattered Telepoint at the Crag of Holla, Dem, or Mea for a cut scene.', sub = {
                { 'Must have Rank 3+ in your home nation' },
                { 'Select the Qufim Island response to continue and complete the cut scene.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-8'] = {
        title        = 'At the Heavens\' Door',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have succeeded in meeting Lion before the mothercrystal. She, too, has seen visions, but hers have implored her to go to Qufim Island.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the Undulating Confluence at (G-8) in Qufim Island.', sub = {
                { 'It\'s close to the Qufim Home Point.' },
            } },
            { 'It is recommended solo players reach at least level 40 before proceeding to the next mission, as the fight is a step more difficult than some players may expect.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 1-9'] = {
        title        = 'The Lion\'s Roar',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A dark vortex has surfaced in Qufim Island, with a strange beast emerging from the depths. Vanquish it to proceed in your journey.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Note that the following fight is considerably more difficult than the content leading up to it. If solo (with up to four Trusts) you may want to reach level 40 to level 50 before attempting.' },
            { 'Examine the Undulating Confluence again to start the battle.', sub = {
                { 'Killing Ophiotaurus by Calling For Help is permitted. The option to do this is next to the combat menu button to Disengage.' },
                { 'The monster will spawn and attack you as soon as you click the Undulating Confluence for the second time, so make sure you already have your trusts out.' },
                { 'You fight against Ophiotaurus. See its page for more information.' },
                { 'The Undulating Confluence doesn\'t disappear, but only one party can have Ophiotaurus popped at a time.' },
                { 'The mission is automatically completed when the Ophiotaurus is defeated.' },
                { 'Examine the Undulating Confluence again for a cutscene.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-1'] = {
        title        = 'Spirits Awoken',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: A samurai from the Far East, Tenzen, has made landfall in Norg, claiming the orb can provide guidance to those who can wield it. This time, a vision bids you to head for Delkfutt\'s Tower.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Lower Delkfutt\'s Tower from Qufim Island for a cutscene.', sub = {
                { 'Warping to the Survival Guide will trigger the cutscene as well. Rezone if it does not.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-10'] = {
        title        = 'Reunited',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Aphmau revealed that the ambassador\'s underlings are after the Astral Candescence. She has offered her aid, and your orb has been filled with light once more. Head to Walahra Temple\'s Hall of Binding.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Walahra Temple and talk to Nadeey for a cutscene.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-11'] = {
        title        = 'Take Wing',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The Hall of Binding was attacked, with a masked woman assaulting the Candescence. Thankfully, Tenzen and Kagero were able to wrest back Phoenix\'s blessing, yet a number of Immortals were injured and the woman escaped. Return to Shararat Teahouse.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Shararat Teahouse at K-12 for a cutscene that will automatically start.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-12'] = {
        title        = 'Prime Number',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The Astral Candescence was likely targeted due to Aht Urhgan\'s prime avatar. They hope to use its power to envelop not just the past, but also the present. Foil their plot by heading to the Alzadaal Undersea Ruins.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into the Alzadaal Undersea Ruins for a cutscene.', sub = {
                { 'Go to the Chamber of Passage and go to the Nyzul Isle Staging Point.' },
                { 'Note: The cost is 200 Imperial Standing points. If you do not have the staging point/imperial standing, you can either use Copper A.M.A.N. Voucher for Imperial Standing points, or grab an Assault tag (Imperial Army I.D. tag) and select the Nyzul Isle Investigation Assault mission in order to port into Alzadaal Undersea Ruins for the cutscene.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-13'] = {
        title        = 'From the Ruins',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Alexander aided Phoenix in reviving Iroha. He knows much about the encroaching darkness, revealing that it\'s something far more sinister than the absence of light. Iroha has been brought back to Aht Urhgan to recover, where she and Aphmau await.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Return to Aht Urhgan Whitegate and click on Imperial Whitegate (The Palace Door) for a cutscene and a Key ItemRhapsody in Crimson.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-14'] = {
        title        = 'Cauterize',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: The world has rejected Iroha\'s presence, but Alexander believes Cait Sith might have an answer. Cavernous maws in either Batallia Downs, Rolanberry Fields, or Sauromugue Champaign may enable you to meet with the enigmatic feline.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to one of the Cavernous Maw in Batallia Downs, Rolanberry Fields or Sauromugue Champaign for a cutscene when you click the sparkling ???.', sub = {
                { '(You may need to be on at least Wings of the Goddess Mission Mission 8: In the Name of the Father to get this cutscene. Verification Needed)' },
                { 'You may not receive this cutscene depending on mission and quest progress. See Ganged Up On for more details.' },
                { 'You must complete the quests Champion of the Dawn and A Forbidden Reunion first if they have been flagged before getting this cutscene.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-15'] = {
        title        = 'Uncertain Destinations',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Cait Sith gave you a special item used to enter the Walk of Echoes after hearing your explanation about what may come to pass. Enter the Walk of Echoes from either Batallia Downs, Rolanberry Fields, or Sauromugue Champaign.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the ??? next to one of the Cavernous Maws in Batallia Downs, Rolanberry Fields or Sauromugue Champaign for a cutscene.', sub = {
                { 'The sparkling blue ???, not the white one.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-16'] = {
        title        = 'Ganged Up On',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Only Altana can make Vana\'diel accept Iroha\'s presence in this world, and the first step to reaching her is to cull the threats that Vana\'diel faces. Continue with the Wings of the Goddess missions if you have not met Lilisette.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Examine the ??? next to one of the Cavernous Maws in Batallia Downs, Rolanberry Fields or Sauromugue Champaign for a cutscene.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-17'] = {
        title        = 'Sacrifice',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though you have met Lilisette, she has no idea how to meet Altana. On the bright side, your orb has been granted another spark of light. Cait Sith has beseeched you for aid, saying that the ambassador has infiltrated the Walk of Echoes.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Enter Walk of Echoes from Pashhow Marshlands (S) (J-9) or Grauberg (S) (F-5) and check the Ornate Door.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-18'] = {
        title        = 'Somber Dreams',
        starting_npc = 'N/A',
        subtitle     = 'Abyssal Purveyor',
        repeatable   = 'No',
        description  = 'Mission Orders: The ambassador threatens to absorb dark energy from Atomos and must be stopped. His minion Cetus has swallowed you whole--vanquish him before proceeding.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'You\'ll automatically be in Grauberg (S)\'s Witchfire Glen and on this mission after the previous cutscene.', sub = {
                { 'Other players who\'ve already done the mission (and helping newer players) are able to use the Walk of Echoes Veridical Conflux to teleport to Witchfire Glen\'s Veridical Conflux; however, they won\'t be able to use the ??? for a return trip at the end of this mission.' },
            } },
            { 'Examine the blue glowing ??? closest to the spot you were teleported to in Grauberg (S) to spawn Cetus.', sub = {
                { 'The correct ??? is NE of the Veridical Conflux and not the one right beside it.' },
                { 'Note: Cetus gains Dread Spikes after Aetheric Pull, so beware if you\'re a returning player using older gear.' },
            } },
            { 'Re-examine the ??? for a cutscene.' },
            { 'Re-enter Walk of Echoes for a cutscene by clicking on the ??? beside the Veridical Conflux.' },
            { 'Note: If you brought some sort of warp as mentioned in the previous mission, warp back into town.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-19'] = {
        title        = 'Of Light and Darkness',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You have successfully vanquished Cetus, but the ambassador escaped, his plan partially successful. Meet with Iroha and discuss your next plans--but first, head back to Norg.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Norg and examine Gilgamesh\'s Oaken Door.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-2'] = {
        title        = 'Crashing Waves',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Having heard about Tenzen, Iroha has headed toward Ru\'Lude Gardens in Jeuno. However, she warns that you must pass the trials posed to you by the chains of Promathia to move forward. Perhaps a fateful meeting awaits you along the way.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Go to Ru\'Lude Gardens and approach the palace. You will get a cutscene at (H-7).', sub = {
                { 'Note: You will not get the cutscene until you have progressed through Promathia Mission 3-2.' },
            } },
            { 'You must obtain the Cipher: Tenzen II in order to complete the mission.', sub = {
                { 'If your inventory was full and you didn\'t receive the cipher, check the Mystic Retriever in Ru\'Lude Gardens at the entrance to the palace.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-20'] = {
        title        = 'Temporary Farewells',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh seemed skittish about a new vortex to Escha that opened in Misareaux Coast. Iroha journeyed there alone, seemingly preferring to travel on her own. Head to Misareaux Coast and see what you can learn.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Misareaux Coast (G-5) and examine the sparkling ??? next to the Undulating Confluence.', sub = {
                { 'The fastest way to get here is by taking the Home Point to Misareaux Coast and walking up the riverbank toward the bridge.' },
                { 'You can also use the Survival Guide, and walk north.' },
