    ['Rhapsodies of Vanadiel Mission 2-23'] = {
        title        = 'Past Imperfect',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Though satisfied with her training, Iroha\'s burden remains heavy, and she is poised to take on the ambassador alone. The two of you have decided to seek out the races of eld. Return to Norg to discuss things.',
        series       = 'Rhapsodies of Vana\'diel',
