    ['Rhapsodies of Vanadiel Mission 2-24'] = {
        title        = 'The Cursed Temple',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gilgamesh has pointed you toward the Temple of Uggalepih, where you should be able to find clues. Depending on your current progress in Rise of the Zilart, there may be some things you must take care of first.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Head to Temple of Uggalepih in Yhoator Jungle (J-11) and enter for a cut scene.', sub = {
                { 'Quick Travel options:', sub = {
                    { 'Survival Guide works as well. Some players reported not receiving this cutscene but still was able to progress in the next step.' },
                    { 'Unity Warp (122) to Yhoator Jungle will take you to Bloodlet Spring, just head south from there to (J-11).' },
                    { 'If you do not have Survival Guide, and you grabbed Den of Rancor HP #1 while completing Zilart Mission 4, you can use escape to be plopped right outside the zone to Temple of Uggalepih.' },
