    ['Rhapsodies of Vanadiel Mission 2-32'] = {
        title        = 'Banishing the Darkness',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Your best hope to meet Altana is to go to Reisenjima. Selh\'teus has vowed to create a new crystal there to banish the Emptiness, and bids you seek one with dominion over magic to help. A friend in Norg may know someone who fits the bill.',
