    ['Rhapsodies of Vanadiel Mission 2-33'] = {
        title        = 'Over the Rainbow',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Iroha claimed that a crystal exists in Reisenjima in her future, which should be no cause for alarm. Over in Norg, your allies have hesitantly encouraged you to visit Shantotto in Windurst Walls.',
        series       = 'Rhapsodies of Vana\'diel',
