    ['Rhapsodies of Vanadiel Mission 2-34'] = {
        title        = 'Cacophonous Discord',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Shantotto, Koru-Moru, and Yoran-Oran discussed Koru-Moru\'s latest experiment, which reacts to the presence of darkness--a darkness which has settled in Escha - Ru\'Aun.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
