    ['Rhapsodies of Vanadiel Mission 2-39'] = {
        title        = 'Both Paths Taken',
        starting_npc = 'N/A',
        subtitle     = 'Spirit Seeker',
        repeatable   = 'No',
        description  = 'Mission Orders: The time has come for Selh\'teus to create a new mothercrystal in Reisenjima. Just as the plan was to be set in motion, the ambassador appeared to challenge Iroha. Stop him in his tracks.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Walk forward to the Transcendental Radiance.' },
            { 'Upon examining the Transcendental Radiance, you will be given the option to enter the battle field:', sub = {
                { 'The fight is against Disjoined One.' },
                { 'Time limit is 15 minutes.' },
                { 'Easily soloable with 5 Trusts.', sub = {
