    ['Rhapsodies of Vanadiel Mission 2-5'] = {
        title        = 'Inescapable Binds',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Iroha was assaulted by the ambassador, who stole away the blessing of Phoenix. Prishe heard that he was off to Aht Urhgan to find the Astral Candescence, which could prove pivotal. The Tenshodo in Jeuno can provide transport to Aht Urhgan.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Zone into Aht Urhgan Whitegate for a cutscene', sub = {
                { 'If you lack access to Aht Urhgan Whitegate speaking with Faursel in Lower Jeuno, (J-8) inside the Tenshodo, select the 3rd invisible option twice, and then selecting "Where is Tenzen" will grant you access.', sub = {
                    { 'This option is unavailable if you have access to Aht Urhgan Whitegate.' },
                } },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-6'] = {
        title        = 'Desert Winds',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Ships to Aht Urhgan regularly depart from Mhaura. It\'s time for you to make the journey.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Obtain a Key Itemboarding permit from the Tenshodo for Aht Urhgan.', sub = {
                { 'If you\'ve already obtained a boarding permit, skip to the next mission. This mission will automatically complete for you when you receive the cutscene from Tenzen in Aht Urhgan Whitegate.' },
            } },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-7'] = {
        title        = 'Ever Forward',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: You successfully rendezvoused with Tenzen in Aht Urhgan, and have been tasked with infiltrating the palace, if possible, or searching out Gessho and joining Salaheem\'s Sentinels otherwise.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'OPTIONAL: Return to your home nation for a cutscene. You will be told to go to the Imperial Whitegate and skip to the mission Aphmau\'s Light.' },
            { 'Examine the Imperial Whitegate for a cutscene.' },
            { 'You will skip to the mission Reunited, receiving Cipher Of Nashmeira\'s Alter Ego II and the ability to view all Treasures of Aht Urhgan mission cutscenes.' },
        },
    },
    ['Rhapsodies of Vanadiel Mission 2-8'] = {
        title        = 'The Endless Sky',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Gessho reported that the ambassador snuck into the palace. If you work hard at Salaheem\'s Sentinels, you may just be able to earn yourself enough trust with the Empire to go in yourself...',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
