    ['Rhapsodies of Vanadiel Mission 3-13'] = {
        title        = 'Become Something More',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: Yve\'noile claims that only a god can stand against the Cloud of Darkness. A human may be able to ascend, but the ambassador banished her before she could explain fully. Head to Reisenjima and consult with Selh\'teus.',
        series       = 'Rhapsodies of Vana\'diel',
        previous     = '',
        next         = '',
        walkthrough  = {
            { 'Return to the Reisenjima Sanctorium for a cutscene.', sub = {
                { '(Reminder: Reisenjima is accessible from the Dimensional Portals at the various Crags: Holla, Mea, and Dem.)' },
            } },
            { 'You will obtain key item Dimensional Compass' },
        },
