    ['Rhapsodies of Vanadiel Mission 3-18'] = {
        title        = 'Sin',
        starting_npc = 'N/A',
        subtitle     = 'None',
        repeatable   = 'No',
        description  = 'Mission Orders: It seems the ambassador was controlled by the Cloud of Darkness, unable to complete its original mission. The god of darkness fused with it, awakening as an entirely new entity. It is beckoning you--go seek it out.',
