    ['Siegemaster Assassination'] = {
        title        = 'Siegemaster Assassination',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Trolls have recruited Borgerlur, a siege specialist from central Aradjiah. The empire cannot allow him to take control of the Troll army. Find and eliminate Borgerlur as he travels through Lebros Cavern.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Assassinate Borgerlur',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Trolls will repop very quickly, try to keep track of which are repops and which are originals. Note that the Borgerlur Troll will never change and once defeated the rest will despawn and the assault will end.' },
            { 'There appears to be some strange behaviour surrounding the Borgerlur troll and also repops. Respawned mobs will have hate on the the target of the Borgerlur Troll if it is engaged.' },
            { 'Repops will now auto agro (this seems to be a recent change)' },
            { 'Repop time is 3 mins 45 seconds' },
            { 'Once Borgerlur is defeated the Rune of Release will spawn at (G-7).' },
        },
    },
    ['The Double Agent'] = {
        title        = 'The Double Agent',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'There is a double agent among the Imperial Qiqirn spies in the Mamool Ja Training Grounds. Find him before he puts the other spies in danger.',
