        },
    },
    ['Deserter'] = {
        title        = 'Deserter',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Agents of our Anti-Corsair Task Force have gone AWOL and are hiding somewhere in Ilrusi. Your mission is to swiftly disarm the deviants and take them into custody. All information on these criminals is highly classified and any disclosure of their identity is strictly prohibited.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Locate the agents',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Weapons can sometimes be broken using critical-hit weaponskills and critical hits.', sub = {
                { 'At iLvl, a Dual Wield job like Red Mage with Haste II/Temper II/etc and two DMG1 daggers would usually break the weapons in about 10 seconds.' },
            } },
            { 'Once the Lamia or Merrow has been disarmed, it will immediately surrender, becoming an NPC.' },
            { 'There are 12 Lamia and Merrow.', sub = {
                { 'The mission can be completed at any time after the first successful subdual by talking to the NPC at the start. Subduing more monsters will result in a higher point reward.' },
                { 'Once all 12 have been killed or subdued, the Rune of Release will automatically spawn if at least one has been subdued.' },
            } },
        },
    },
    ['Egg Conservation'] = {
        title        = 'Egg Conservation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'There have been reports that Qiqirn hunters have been collecting the eggs of our army\'s messenger apkallus. You are to join forces with the male apkallus in the area and eliminate the invading Qiqirn while protecting the females and their eggs.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Drive out the hunters',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'All Apkallu are curable and buffable.' },
            { 'Smaller apkallu are female. They will not aid the players.', sub = {
                { 'The assault is a failure if all female Apkallu are defeated.' },
            } },
            { 'Larger apkallu are male. They will automatically attack any nearby Qiqirn.', sub = {
                { 'If they are damaged beyond 50%, they will fall over and stop aiding the party.' },
            } },
            { 'Qiqirn will slowly approach in pairs or solo from the east and west side; player should not stray too far from the gaggle of apkallus.' },
            { 'Drag the Qiqirn through the middle of the pack of Apkallu to get the male Apkallu assisting in the fight.' },
        },
    },
    ['Imperial Code'] = {
        title        = 'Imperial Code',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Empire\'s mercury cipher (OGMA) has been stolen by a group of far eastern spies. With it, our enemies will be able to decrypt top-secret military orders, thus severely compromising Imperial safety. You are to intercept the enemy as they transfer the device.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Chief Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Retrieve the OGMA',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'You must defeat 3 NIN NMs: Oko, Danzo and Saizo. They will each leave behind a ??? after their corpse has faded, the last of which will be the OGMA, which when retrieved will spawn the Rune of Release.', sub = {
                { 'Oko and Danzo both dual wield katanas, while Saizo uses a great katana and can also use Mijin Gakure. Oko and Saizo both have a Kusa very nearby them, which you should probably attempt to pull first if you don\'t have a way to sleep the Kusa.' },
            } },
            { 'The Rune of Release will spawn on the border of (G-8) and (H-8) on the lower level. It will be right under a drop-down from the top level.' },
        },
    },
    ['Marids in the Mist'] = {
        title        = 'Marids in the Mist',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Our agents have informed us that the Mamool Ja have been training marids to use during sieges on the Empire. You are to locate these deadly beasts and capture or eliminate them before it\'s too late.',
