    ['Breaking Morale'] = {
        title        = 'Breaking Morale',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Scouts report that the new Mamool Ja soldiers have recieved supplies from their families. Destroy Mamool Ja morale by stealing these supplies while being careful to remain undetected.',
