    ['Demolition Duty'] = {
        title        = 'Demolition Duty',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A confidential report states that corsairs are secretly collecting the remains of shipwrecks on the Ilrusi Atoll. Use the automaton issued to you by the on-site engineer to demolish these shipwrecks.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Lance Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Demolish the shipwrecks',
        recommended_lv = 'Lvl. 50',
        walkthrough  = {
            { 'There are five ship wrecks. See the map for more details.' },
            { 'To be assigned an automaton, talk to the starting NPC.', sub = {
                { 'The party can only have one automaton.' },
                { 'The person who talks to the starting NPC will be designated the automaton\'s master.' },
            } },
            { 'The automaton will follow its master around until it finds wreckage to demolish.' },
            { 'Only the automaton can attack the wreckage. However, you can use AoE abilities and spells on targets near adjacent wreckage to cause damage to the wreckage.' },
            { 'Each time the automaton uses a weaponskill on a wreckage, a Carrion Crab will spawn and attack the automaton.', sub = {
                { 'The crab cannot be distracted from the automaton. However, the automaton can be cured and crabs only have about 2000 hp.' },
            } },
            { 'If the automaton is killed or despawns due to its master dying, a new one can be obtained by talking to the start NPC again.' },
            { 'If the automaton is damaged, the party can opt to repair the automaton at the start NPC.' },
            { 'After the wreckages are demolished, talk to the starting NPC to spawn the Rune of Release' },
        },
    },
    ['Evade and Escape'] = {
        title        = 'Evade and Escape',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The unit deployed within Lebros Cavern is in danger of being overwhelmed by the well-positioned enemy. Discover an alternate route so they can retreat in safety.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Lance Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Discover alternate route',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'The switches will be up in 3 of a possible 7 locations. Each of the possible locations are at the dead-ends on the extremeties of the map.' },
        },
    },
    ['Shanarha Grass Conservation'] = {
        title        = 'Shanarha Grass Conservation',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Rabbits are sending shanarha grass, unique to the Leujaoam Sanctum, to the verge of extinction. Drive away the rabbits and protect the vegetation.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Lance Corporal',
        time_limit   = '30 minutes',
        mission_orders = 'Protect the vegetation.',
        recommended_lv = 'Lvl. 50',
        walkthrough  = {
            { 'You begin at (I-9) as do all 20 Conies. Shortly after the Assault begins they will split and start moving either north or south.' },
            { 'Sometimes the Conies will run away while engaged, eventually losing aggro. Note that if they run past other Conies they will link. If a Coney runs away and loses aggro, if left unclaimed they will recover to full HP.' },
            { 'It is recommended to wait a few minutes after the Assault begins to allow the Conies to spread out and avoid a mass link.' },
            { 'Once a Coney reaches a vegetation they will eat it until it disappears. The Assault is automatically failed if too much vegetation is eaten.' },
            { 'Assault Points are based on the number of vegetation remaining. The more vegetation remaining at the end of the Assault will reward more Assault Points.' },
        },
    },
    ['Shooting Down the Baron'] = {
        title        = 'Shooting Down the Baron',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'An imp known as the Black Baron has hit Periqia like a meteor strike, single-handedly defeating 79 imperial soldiers. The Empire cannot suffer any more losses. It is time for the baron to meet his end.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Lance Corporal',
        time_limit   = '15 minutes',
        mission_orders = 'Eliminate the Black Baron',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'You will enter the Assault on the east side of the map in the room at (I-8). This is also where the Rune of Release spawns.' },
            { 'The Black Baron will not appear on Widescan.' },
            { 'A short time after he is engaged the Baron will warp away to a different part of the map. For this reason having a job that can summon a pet to follow him to his next location is extremely useful, as it will save a lot of time. /SMN is also fine for this. It should be noted that at ilvl 119 the Black Baron dies in one weaponskill. The pet strategy is no longer necessary.' },
            { 'While he has significantly more HP, he is otherwise pretty much the same as a regular VT Imp.' },
        },
    },
    ['Lamia No.13'] = {
        title        = 'Lamia No.13',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Your mission is to hunt down Lamia No.13, a fearsome creature known to have performed vile experiments on the countless corpses of her enemies.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Private First Class',
        time_limit   = '30 minutes',
        mission_orders = 'Eliminate Lamia No.13',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'In this Assault, you start at I-8 with your goal to defeat a RNG-type Lamia NM named Lamia No. 13. She is located in the northern part of the map, and assisted by 3 NPCs that she has charmed, which must be dealt with if you are to succeed.' },
            { 'The most popular strategy is to bring 2-3 jobs that are capable of Dispelling the Charmed status from the NPCs, as they will then join your efforts to defeat the Lamia. Jobs that are capable of Dispelling Charm include RDM, BRD, COR, SMN and BLU. In addition, due to the innate accuracy of the Dispel (or Finale) spells, players level 64 (or 66) and higher may sub RDM (or BRD) for the ability to Dispel.' },
            { 'Lamia No. 13 will use Belly Dance often, re-Charming those in range, so players must be ready to Dispel again.' },
        },
    },
    ['Lebros Supplies'] = {
        title        = 'Lebros Supplies',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'An advance unit sent into Lebros Cavern has met heavy resistance and is in need of reprovisioning. Your mission is to deliver rations to each member of the advance unit.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Private First Class',
        time_limit   = '30 minutes',
        mission_orders = 'Deliver the provisions',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'Yazuhma will keep you supplied with tasty treats for those hard working soldiers. She will only give one supply out every few seconds, so at the beginning you will have to wait as she hands things to you one by one.' },
            { 'Yazuhma will report to you how many soldiers are still hungry with the following messages:' },
        },
    },
    ['Orichalcum Survey'] = {
        title        = 'Orichalcum Survey',
        starting_npc = '',
