    ['Excavation Duty'] = {
        title        = 'Excavation Duty',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Imperial Army plans to traverse Lebros Cavern as part of their attack on Halvung, however the tunnels are blocked with rocks. You must remove the obsctructions.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Private Second Class',
        time_limit   = '30 minutes',
        mission_orders = 'Protect the Professor',
        recommended_lv = 'Lvl. 50',
        walkthrough  = {
            { 'Brittle Rocks can be destroyed through damage, and damage over time is a very good way to do it. SCH/BLM can cast Bio, three non-overlapping elemental DoTs (e.g. Shock, Burn, Choke), and Helix. Immune to Poison II' },
            { 'Volcanic Bombs aggro sight and can be completely avoided with Invisible (Status).' },
            { 'Qiqirn Volcanists and Ceramists will occasionally drop Qiqirn Mine Temporary Items to help destroy the rocks.', sub = {
                { 'Once you have obtained a mine, engage a Brittle Rock and use the temporary item. Stay engaged until the device detonates and the rock will be destroyed in a single blast.' },
                { 'At Item Level 117+, you can kill Qiqirn way faster than the walls, so it\'s worth trying to get bombs from them. Be sure to only kill one at a time.' },
            } },
            { 'The Rune of Release will spawn at the dead end room at (F-10) when the last Brittle Rock is defeated.', sub = {
                { 'In order to save time, a party member can be sent towards the Rune while the last Brittle Rock is being fought.' },
            } },
        },
    },
    ['Golden Salvage'] = {
        title        = 'Golden Salvage',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Rumor has it that the golden figurehead from the Black Coffin, the ship of Luzaf the pirate, can be found somewhere within Ilrusi Atoll.',
