    ['Seagull Grounded'] = {
        title        = 'Seagull Grounded',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Immortals have captured a member of the Seagull Phratrie, a rebel organization. You are to escort the prisoner safely to a holding area.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Private Second Class',
        time_limit   = '30 minutes',
        mission_orders = 'Escort the prisoner',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Excaliace will move automatically when a party member is a few yards behind him.', sub = {
                { 'Excaliace will stop at certain points if party members are crowding him and remark, "Someone\'s been eating too much garlic..."' },
                { 'If no party members are close to Excaliace, he try to escape by running away, "Now\'s my chance!" If he is successful, the mission is a failure.' },
                { 'If Excaliace encounters a monster, he will run away.' },
            } },
            { 'Excaliace will investigate one room labeled \'A\', one room labeled \'B\', and one room labeled \'C\' on the map below.', sub = {
                { 'If the room contains Arrapago Crabs, you must defeat the crabs before he enters the room.' },
            } },
            { 'At the junction in (H-8), Excaliace will choose to go towards the label \'D\' or the label \'E\'. In either case, the path ahead of him will contain 2 or 3 Periqia Pugils and possibly a Debaucher which need to be cleared.' },
            { 'In (G-10) there is a Debaucher which needs to be taken care of. It is possible to pull the Debaucher to the side so that Excaliace can pass by while the party deals with the monster.' },
            { 'In the final room there is a Debaucher. It can be pulled away so that Excaliace does not see it.' },
            { 'The Rune of Release spawns in the northwest corner of the room, where Excaliace completes his patrol.' },
        },
    },
    ['Apkallu Breeding'] = {
        title        = 'Apkallu Breeding',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Due to their intelligence and ability to travel through both water and on land, the rare Lebros Apkallu is prized by the navy as a messenger bird. Help increase their numbers by pairing them up.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant',
        time_limit   = '15 minutes',
        mission_orders = 'Match the apkallu',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'The apkallus in this assault speak in morse code. And you thought they were annoying in Apkallu Seizure!' },
        },
    },
    ['Apkallu Seizure'] = {
        title        = 'Apkallu Seizure',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Famous biologist Professor Clavauert is researching apkallu on Ilrusi Atoll. The more discoveries he makes in Aht Urhgan, the more likely he is to join the Empire. Assist him by capturing apkallu.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Capture the apkallu',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'First, obtain a Hamsi by finding and clicking on one of the many ??? that are scattered about the map.' },
            { 'Once you have a delicious fish, find a passive Fairy Apkallu. Stand in front of it at a medium-short distance, close enough to select the target.' },
        },
    },
    ['Imperial Treasure Retrieval'] = {
        title        = 'Imperial Treasure Retrieval',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A Puk recently stole a treasure box containing enchanted gems from the royal treasury. The gems were then given to Mamool Ja officers as a reward for duty. Find and retrieve the treasure.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant',
