        mission_orders = 'Recover the treasure',
        recommended_lv = 'Lvl. 50',
        walkthrough  = {
            { 'The Mamool Ja Savage\'s team is comprised of:', sub = {
                { 'Mamool Ja Governor' },
                { 'Red Badge Mamool Ja' },
                { 'Blue Badge Mamool Ja' },
