    ['Stop the Bloodshed'] = {
        title        = 'Stop the Bloodshed',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Lamiae are preparing to release swarms of chigoes in Al Zahbi to collect blood samples. Destroy the chigoes and thwart their plan.',
        series       = '',
