    ['Supplies Recovery'] = {
        title        = 'Supplies Recovery',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A logistics unit headed to the front lines of the war with the Far East was attacked and their supplies were stolen. The enemy then fled towards Leujaoam Sanctum. An Immortals unit will also join in the recovery.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant',
        time_limit   = '30 minutes',
        mission_orders = 'Retrieve the supplies',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'The goal of the assault is to collect more supplies than the immortals.', sub = {
                { 'Supplies are temporary items dropped from Imps.' },
            } },
            { 'Imps will not appear anywhere on the map until one player talks to the NPC Kuihlud at the start.' },
        },
    },
    ['Azure Ailments'] = {
        title        = 'Azure Ailments',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'To protect against an outbreak of the dreaded kraken flu, data is required on the effects of the disease. Healthy volunteers are wanted to travel to the Mamool Ja Training Grounds and collect important supplies.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Second Lieutenant',
        time_limit   = '30 minutes',
        mission_orders = 'Gather pathological data',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Collect 3 status effects and talk to Garjham a second time to unlock the rune of release.' },
            { 'Status effects:', sub = {
                { 'Amnesia -- Qiqirn Huckster, kibosh' },
                { 'Bio (Status) -- Poroggo, spell' },
                { 'Disease -- Pit Lindwurm, foul breath' },
                { 'Slow (Status) -- Huge Spider, spider web or Pit Lindwurm, Chomp Rush' },
                { 'STR Down -- Bugard, awful eye' },
                { 'Attack Down -- Leech, acid mist (aoe)' },
                { 'Evasion Down -- Slavering Lizard, infrasonics (conic)' },
            } },
        },
    },
    ['Operation: Black Pearl'] = {
        title        = 'Operation: Black Pearl',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A ship carrying Princess Kadjaya of the Imperial family back from a diplomatic mission to the West has run aground near the Lebros Cavern. You are to find the survivors and escort them to safety.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Second Lieutenant',
        time_limit   = '30 minutes',
        mission_orders = 'Rescue Princess Kadjaya',
        recommended_lv = 'Lvl. 70',
