    ['Wake the Puppet'] = {
        title        = 'Wake the Puppet',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'During a previous mission to eradicate the Undead Swarm presence from Periqia, the Imperial forces were forced to abandon several Mark-II automatons upon their retreat. You are to infiltrate the area, locate the machines, and aid in their return to Al Zahbi.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Second Lieutenant',
        time_limit   = '30 minutes',
        mission_orders = 'Retrieve the Mark-IIs',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Puppets spawn in the 4 dead end rooms at (H-6), (F-8), (J-8), (H-10).', sub = {
                { '2 puppets will spawn in each of 3 rooms; the 4th room will be empty.' },
            } },
            { 'The area is initially empty of Wights; they will only spawn when a puppet is active.' },
            { 'When a puppet is located, it can be activated by emoting /salute, targeting the puppet. The puppet will then treat the player as its master.', sub = {
                { 'A player may only be master of one puppet at a time.' },
                { 'A puppet may only have one master at a time.' },
                { 'Emotes must be performed within 10\' of the puppet. They can be done as motions to reduce chat spam (e.g. "/clap motion").' },
                { 'After activating a puppet, you don\'t have to target it for the emote to work.' },
            } },
            { 'By emoting /clap while near the puppet, the master can instruct the puppet to move to where the master is standing.' },
            { 'By emoting /goodbye, the puppet will be deactivated and the player is no longer its master.', sub = {
                { 'If the puppet is deactivated close to the starting NPC, the puppet\'s name will turn green and the puppet is considered "returned".' },
            } },
            { 'By emoting /hurray while near the puppet, the master can instruct the puppet to enter combat mode.', sub = {
                { 'While in combat mode, the puppet will automatically engage a nearby target.' },
                { 'While in combat mode, the puppet will ignore all other commands until its target is defeated and it returns to normal operation.' },
            } },
            { 'Occasionally, the puppet will stop responding to all commands and will repeatedly display an emotion. To return the puppet to normal operation, the master must respond with another emote.' },
        },
    },
    ['Azure Experiments'] = {
        title        = 'Azure Experiments',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Imperial alchemists have developed various tissues to graft onto and strengthen the bodies of the Immortals, but they need test subjects for clinical experiments. Go lend your assistance.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant Major',
        time_limit   = '30 minutes',
        mission_orders = 'Become a test subject',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Speak to Nareema to receive a random graft. This spawns a group of Lamiae in one of four spots (two to the west, one to the south, and one to the east.) The grafts are:', sub = {
                { 'Dragonfly Optical Tissue:+Acc/Racc -Atk/Ratk' },
                { 'Goobbue Muscle Tissue:+100% atk, +100% slow' },
                { 'Opo-opo Cerebral Tissue:MP -50%, Fast Cast' },
                { 'Raptor Tissue: Movement Speed +100%, HP -50%' },
            } },
            { 'After defeating each group of Lamiae, talk to Nareema again for another graft to spawn the next group.' },
            { 'After all four groups are defeated, the Rune of Release will spawn back at the starting point at (G-7).', sub = {
                { 'Since the eastern spawn point is down a one-way drop that requires you to walk in a loop to get back to the start, ranged pulling is recommended.' },
            } },
        },
    },
    ['Blitzkrieg'] = {
        title        = 'Blitzkrieg',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'After shedding their skins, the Mamool Ja gather for a festival to celebrate their new scales and dance until exhausted. This is a prime opportunity to catch them off guard!',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant Major',
        time_limit   = '30 minutes',
        mission_orders = 'Annihilate the enemy',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'In order to make the Rune of Release spawn, kill 200 monsters.' },
            { 'If you hold pets and kill mostly Mamool Ja, the NM Bluethunder Kaqool Ja will spawn. He has more HP (3500?) and when defeated, drops a Blackscale Key.', sub = {
                { 'This key can be used to free the caged NPC Lumaayu at (I-6), which will spawn an additional 100 monsters.' },
                { 'In the final wave of monsters, the NM Festive Firedrake spawns. Kill him to maximize AP reward.' },
            } },
            { 'The Rune of Release will spawn where the player first enters the map.' },
        },
    },
    ['Defuse the Threat'] = {
        title        = 'Defuse the Threat',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Lamiae have hired Qiqirn demolition experts to set land mines in Periqia. You must eliminate this hazard for the soldiers.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant Major',
        time_limit   = '30 minutes',
        mission_orders = 'Clear the mine fields',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'Mines are invisible and do not show up on Widescan.' },
            { 'When a player approaches a mine, it will trigger a timer. The player then has 30 seconds to locate the mine.' },
        },
    },
    ['Lost and Found'] = {
        title        = 'Lost and Found',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The Empress\'s uncle Bashalab visited Ilrusi Atoll in secret and lost his ring, the "Eye of Zahak." Escort the royal family\'s hired agent through Ilrusi Atoll and find his lost ring.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant Major',
        time_limit   = '30 minutes',
        mission_orders = 'Find the ring',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'The best way of doing this is to find the first clue with party members spread out on the map as you try to triangulate the rings position.' },
        },
    },
    ['Wamoura Farm Raid'] = {
        title        = 'Wamoura Farm Raid',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The enemy has begun raising swarms of wamoura in the Lebros Caverns. If they reach adulthood, they would present a formidable threat. Infiltrate the Lebros Caverns and destroy them.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Sergeant Major',
        time_limit   = '30 minutes',
        mission_orders = 'Remove the threat',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'After a certain amount of time, some of the Wamouracampa will evolve into Wamouras.' },
            { 'The Rune of Release will spawn in the southwest of (H-8) when all Ranch Wamourcampas and Ranch Wamouras have been defeated.' },
        },
    },
    ['Escort Professor Chanoix'] = {
        title        = 'Escort Professor Chanoix',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A longhaired marid has been found frozen in the eternal ice of Leujaoam Sanctum. Escort Professor Clavauert B Chanoix to the site of the discovery.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Superior Private',
        time_limit   = '30 minutes',
        mission_orders = 'Protect the Professor',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'Once entering the Assault, the Professor will begin to move once someone moves past him. There is no need to interact with him to make him move. Likewise, he will not stop moving once he starts.' },
            { 'All enemies in the Assault can aggro the Professor if he gets too close to them.' },
            { 'It is recommended to run ahead of the Professor to defeat enemies before they aggro him.' },
            { 'The Professor does not have a lot of HP. You are able to heal him using Cure spells. However, you are unable to use any party-specific healing spells such as Magic Fruit or Curing Waltz. You may also cast Protect and Shell on him.' },
            { 'Occasionally, the Professor will take a break and stop moving at certain intervals. You make take this time to heal him or yourself.' },
            { 'While you may avoid aggro with Sneak, the Professor will continue to aggro enemies.' },
            { 'As all enemies in the Assault are Undead, you may aggro with low HP (yellow or red HP).' },
            { 'Gelid Bhoots will often cast Blizzaga III which can be dangerous to the Professor and your party.' },
            { 'The Assault will be automatically failed if Clavauert B Chanoix is defeated.' },
        },
    },
    ['Extermination'] = {
        title        = 'Extermination',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'The vermin feasting on the corpses left behind by the Lamiae have multiplied to unnatural numbers. Destroy this threat to the surrounding ecology.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Superior Private',
        time_limit   = '30 minutes',
        mission_orders = 'Exterminate all monsters',
        recommended_lv = 'Lvl. 70',
        walkthrough  = {
            { 'Defeat all monsters to complete this assault' },
            { 'Randomly, one monster will repop as Undead shortly after being defeated. The undead version must be defeated as well.' },
            { 'The map shows the approximate location of all monsters. Use it.' },
        },
    },
    ['Sagelord Elimination'] = {
        title        = 'Sagelord Elimination',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'Sagelord Molaal Ja is visiting the training grounds to oversee the progress of the soldiers. His elimination would sow chaos and confusion in the Mamool Ja ranks.',
        series       = '',
        previous     = '',
        next         = '',
        assault_rank = 'Superior Private',
        time_limit   = '30 minutes',
        mission_orders = 'Defeat Sagelord Molaal Ja',
        recommended_lv = 'Lvl. 60',
        walkthrough  = {
            { 'The area of this assault is filled with Mamool Ja Trainees that will aggro and link to Molaal Ja.' },
            { 'When Molaal Ja links Trainees, they will only initially be aware of the target that Molaal Ja currently hates.', sub = {
                { 'The Trainees will not deaggro naturally, but if nobody acts upon them, they will go passive when they kill their only target.' },
                { 'While not too dangerous individually, the swarm of Trainees caused by a fleeing Molaal Ja can cause a wipe. Make sure to use Reraise (Status) in the event of a wipe.' },
                { 'Assigning someone to preemptively aggro and kite Trainees (especially someone with movement speed enhancement) will prevent Molaal Ja from linking anything when he runs away.' },
            } },
            { 'Using a pet (such as Carbuncle) or Widescan can help the party locate Molaal Ja quickly when he runs away.' },
        },
    },
    ['Saving Private Ryaaf'] = {
        title        = 'Saving Private Ryaaf',
        starting_npc = '',
        subtitle     = '',
        repeatable   = '',
        description  = 'A squad sent in to search for the Seagull Phatrie hideout has failed to report. Find any survivors, especially one Private Ryaaf, a relative of the Galeserpent General.',
        series       = '',
