        walkthrough       = {
            { 'To start this quest, speak to Sigismund on top of the Orastery at (E-7) of Port Windurst. He tells you about the elusive Starfall Tear.' },
            { 'Speak with Tohopka, who is standing right next to Sigismund, at (E-7). Tohopka tells you how to collect the tears. You\'ll need to obtain some Pugil Scales. Pugils drop them, or you can find them under the AH category Bonecrafting. If there are no Scales on the AH, you can kill Pugils just outside in East Sarutabaruta for some.' },
            { 'You can also find the Starfall Tear on the AH under the "Other" category.' },
            { 'With some Scales in you possession, head out to West Sarutabaruta. On the map, there is a place called the "Starfall Hillock." In the general vicinity of that area, at (I-6), you will find the Twinkle Tree. If you\'re having trouble finding the tree, it\'s a somewhat rounded tree that has a blue firefly-type glow during the nighttime.' },
            { 'Wait until the hours of 0:00 to 3:00 game time. At any other time, the tree gives the message "There is nothing out of the ordinary here," but during those three hours you\'ll receive another message: "A frost deposit at the base of the tree twinkles in the starlight." At this point, trade the Pugil Scales and you\'ll receive your Starfall Tear.' },
            { 'Head back to Sigismund and give him the Tears. He gives you a Fish Scale Shield as a reward.' },
        },
    },
    ['Toraimarai Turmoil'] = {
        title             = 'Toraimarai Turmoil',
        starting_npc      = 'Ohbiru-Dohbiru, Windurst Waters South (J-9)',
        subtitle          = 'Certified Rhinostery Venturer',
        repeatable        = 'Yes',
        description       = 'Become a certified Rhinostery adventurer in order to enter the Toraimarai Canal and cull the Starmites that are causing havoc there. Bring back the shells of three Starmites to receive your reward.',
        required_fame     = 'Windurst Fame Level: 6',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Starmite Shell x3',
        rewards           = '4,500 Gil Key Item Rhinostery certificate',
        previous_quest    = 'Blue Ribbon Blues',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Ohbiru-Dohbiru for a cutscene. You will receive a Key Item Rhinostery certificate.', sub = {
                { 'The Key Item Rhinostery certificate provides access to Toraimarai Canal through Windurst Walls (H-3).' },
            } },
            { 'Trade Ohbiru-Dohbiru 3 Starmite Shells to complete this quest.', sub = {
                { 'Starmite Shells drop off Starmites in Toraimarai Canal.' },
                { 'To find Starmites, enter Toraimarai Canal by speaking to Seven of Diamonds Windurst Walls (H-3).', sub = {
                    { 'Head east at the first intersection.' },
                    { 'At (I-8) go down the stairs, then head east.' },
                    { 'Turn right at the two intersections at (I-10).' },
                    { 'Go up the stairs at (I-9).' },
                    { 'Head west to (G-9) to find where the Starmites spawn.' },
                } },
            } },
        },
    },
    ['Trust: Windurst'] = {
        title             = 'Trust: Windurst',
        starting_npc      = 'Wetata, Windurst Woods',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Wetata of the Jeuno Institute of Magical Studies has introduced you to the Trust initiative and asked you to visit Kupipi in Heavens Tower.',
        required_fame     = 'Windurst Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Level 5 on any job',
        rewards           = 'Green institute card Windurst Trust permit Able to use Windurstian Trust Spells Trust Spell: Kupipi',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Wetata in Windurst Woods at (G-10), she will give you the Green institute card.' },
            { 'Head to Heavens Tower and speak to Kupipi.', sub = {
                { 'If this is not your first Trust quest that you are completing, at this point you will be finished with the quest and receive the Windurst Trust permit.' },
                { 'If this is your first Trust quest, you must use the Trust magic spell "Kupipi" in either West Sarutabaruta or East Sarutabaruta. After, return to Kupipi for the Windurst Trust permit.' },
            } },
        },
    },
    ['Truth, Justice, and the Onion Way!'] = {
        title             = 'Truth, Justice, and the Onion Way!',
        starting_npc      = 'Kohlo-Lakolo, Port Windurst (G-5)',
        subtitle          = 'Star Onion Brigade Member',
        repeatable        = 'No',
        description       = 'If you want to join the Star Onion Brigade, you had better bring Kohlo-Lakolo some kind of "tail."',
        required_fame     = 'Windurst Fame Level: 1',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Rarab Tail',
        rewards           = 'Justice Badge',
        previous_quest    = 'None',
        next_quest        = 'Know One\'s Onions',
        walkthrough       = {
            { 'Talk to Kohlo-Lakolo behind warehouse #1 at G-5 in Port Windurst for a cut-scene.' },
            { 'Obtain and trade him a Rarab Tail for a cut-scene and your reward to complete the quest.' },
        },
    },
    ['Tuning In'] = {
        title             = 'Tuning In',
        starting_npc      = 'Leepe-Hoppe, Windurst Waters South (J-9)',
        subtitle          = 'Fine Tuner',
        repeatable        = 'No',
        description       = 'A Mithran Tracker has demanded the construction of a new type of tuning fork so she can converse with the sleeping gods. Help Leepe-Hoppe gather the necessary materials.',
        required_fame     = 'Windurst Fame Level: 4',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Extra-Fine File Spruce Lumber Magicked Steel',
        rewards           = '4000 gil',
        previous_quest    = 'None',
        next_quest        = 'Tuning Out',
        walkthrough       = {
            { 'Speak with Leepe-Hoppe to start the quest.' },
            { 'Leepe-Hoppe requires 3 items, all of which must be farmed from Chains of Promathia areas.', sub = {
                { 'An Extra-Fine File can be found by defeating Fomor in Lufaise Meadows. Specifically, Fomor Warrior, Fomor Monk, Fomor Dark Knight, Fomor Paladin, and Fomor Samurai.' },
                { 'A piece of Spruce Lumber can be found by defeating Taurus in Phomiuna Aqueducts. 3 Taurus can be found at (G-6) of Map 1. Enter Phomiuna Aqueducts from Tavnazian Safehold, or use the Survival Guide and head northwest.' },
                { 'An ingot of Magicked Steel is found on various Goblins in Oldton Movalpolos. It is advised to farm Goblin Oilman, as anecdotal reports show these mobs have a higher drop rate. Use the Proto-Waypoint, drop down the ledge, and head West.' },
            } },
            { 'You need to trade all 3 of these items to Leepe-Hoppe at once to complete the quest. Speak to Leepe-Hoppe again to start the Tuning Out quest.' },
        },
    },
    ['Tuning Out'] = {
        title             = 'Tuning Out',
        starting_npc      = 'Leepe-Hoppe, Windurst Waters South (J-9) - Home Point #3)',
        subtitle          = 'Friend of the Helmed',
        repeatable        = 'No',
        description       = 'The Mithran Tracker has taken the new tuning fork and left for a fabled protocrystal said to exist in the Northlands. She has failed to return. Assist Ildy-Goldy in gathering information about the tracker\'s whereabouts.',
        required_fame     = 'Windurst Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'Chains of Promathia',
        requirements      = 'Habaneros Black Curry Mutton Tortilla',
        rewards           = '6,000 gil Cache-nez',
        previous_quest    = 'Tuning In',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Leepe-Hoppe to initiate the quest, you must wait one earth minute from completing Tuning In.' },
            { 'Speak with Jakoh Wahcondalo at (J-9) in Kazham.' },
            { 'Speak with Romaa Mihgo at (H-11) in Kazham.' },
            { 'Travel to (K-7) of Yuhtunga Jungle and search for a ??? overlooking Gemini Falls. Be warned though; this cutscene will spawn 5 Nasus that you must defeat. The Nasus are easily killable by a level 75 job.', sub = {
                { 'Only one player can initiate and receive the quest cutscenes at the ???. Other players must wait 3 minutes after the defeat of the Nasus before being able to spawn their own NM and receive the the following cutscene.' },
                { 'This side of the falls can be accessed from a tunnel in (I-7), you do not need to go through Ifrit\'s Cauldron.' },
            } },
            { 'Click the ??? at (K-7) of Yuhtunga Jungle again after defeating the Nasus.' },
            { 'Return to Kazham and speak with Romaa Mihgo.' },
            { 'To progress any further it is mentioned you will need a Mutton Tortilla, Habaneros, and a serving of Black Curry.', sub = {
                { 'Habaneros can be bought from the Auction House, bought from regional vendors, via Herb Seeds planted in your Mog Garden, or farmed from Mantraps in Misareaux Coast.' },
                { 'Black Curry can be bought from the Auction House.' },
                { 'Mutton Tortilla can also be bought from the Auction House, but it is probably better to purchase it from Taajiji in Windurst Waters\' Timbre Timbers Taverns.' },
            } },
            { 'After getting your food items, head to Norg and speak with Comitolus at (K-8).' },
            { 'Trade Comitolus your items to receive the next cutscene. You will be told to head to Beaucedine Glacier and meet up with the Rhinostery researchers there.' },
            { 'In Beaucedine Glacier head to (I-7) and speak with Torino-Samarino at the tower. After this cutscene you will receive your 6000 gil, title, and the Quest will be marked completed in your log.' },
            { 'Speaking to Leepe-Hoppe - Windurst Waters - Home Point 3 - after completing the quest will reward you with a Cache-nez' },
        },
    },
    ['Twinstone Bonding'] = {
        title             = 'Twinstone Bonding',
        starting_npc      = 'Gioh Ajihri, Windurst Woods (K-5)',
        subtitle          = 'Bond Fixer',
        repeatable        = 'Yes',
        description       = 'Twenty years ago, there was a great battle between the Mithra and the Yagudo in the Meriphataud Mountains. Gioh wants you to collect the twinstone earrings that belonged to the Mithra warriors who fell there.',
        required_fame     = 'Windurst Fame Level: 3',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Twinstone Earring',
        rewards           = 'First completion: Wrapped Bow Subsequent completions: 900 gil',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak with Gioh Ajihri in Windurst Woods at (K-5) to begin the quest. She asks for a Twinstone Earring.', sub = {
                { 'The earring can either be found on the AH or you can farm it.' },
                { 'Hill Lizards in Meriphataud Mountains drop the item, if you want to farm it.' },
            } },
            { 'Bring the Twinstone Earring back to Gioh for your reward.' },
        },
    },
    ['Unbridled Passion'] = {
        title             = 'Unbridled Passion',
        starting_npc      = 'Perih Vashai, Windurst Woods (K-7)',
        subtitle          = 'Paragon of Ranger Excellence',
        repeatable        = 'Yes, after Memory reset',
        description       = 'Semih Lafihna has set out to find the truth. Track her down and help her in any way possible.',
        required_fame     = 'Windurst Fame Level: 1',
        level_restriction = 'Level 50+ Ranger',
        pack              = 'None',
        requirements      = 'Key Item Koh\'s letter Gold Earring',
        rewards           = 'Hunter\'s Socks Ice Arrow x99',
        previous_quest    = 'Fire and Brimstone',
        next_quest        = 'none',
        walkthrough       = {
            { 'Talk to Perih Vashai in Windurst Woods (K-7) for a cutscene where she will tell you to go to Mhaura.' },
            { 'In Mhaura speak twice with Koh Lenbalalako (F-9) for a cutscene. She will ask you for a Gold Earring. Trade it to her for a second cutscene and get the key item Koh\'s letter.', sub = {
                { 'Gold Earring can be obtained for free by completing the RoE - Conflict: Xarcabard objective for the first time.' },
            } },
            { 'Zone into Xarcabard for a cutscene hinting to look near Castle Zvahl Baileys.', sub = {
                { 'Most convenient warp is Survival Guide - Castle Zvahl Baileys' },
            } },
            { 'Find the cave at (E-7) in Xarcabard and examine the ??? where you will get another cutscene and then a Koenigstiger will pop. Defeat it.', sub = {
                { 'If you are doing multiple, everyone must get their own cutscene and kill. It has a ~3 minute repop.' },
            } },
            { 'Now head south to the cave at (E-8) and check the ??? here for another cutscene.' },
            { 'After the cutscene is over, check the ??? again for 99 Ice Arrows.', sub = {
                { 'This step may be optional.Verification Needed' },
            } },
            { 'Head back to Windurst Woods and talk once more to Perih Vashai for the final cutscene and your reward.' },
        },
    },
    ['Waking Dreams'] = {
        title             = 'Waking Dreams',
        starting_npc      = 'Kerutoto, Windurst Waters South (J-8) (HP #3)',
        subtitle          = 'Heir to the Realm of Dreams',
        repeatable        = 'Yes',
        description       = 'Diabolos has informed Kerutoto that he is waiting for you at the Shrouded Maw in Pso\'Xja, buried deep in the northern lands. You must respond to his summons so that Kerutoto can meditate free of trouble.',
        required_fame     = 'Windurst Fame Level: 3',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Darkness Named',
        rewards           = 'Diabolos (Avatar) 15,000 Gil Diabolos\'s Pole Diabolos\'s Earring Diabolos\'s Torque Diabolos\'s Ring',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Kerutoto, Windurst Waters South (J-8) HP #3, for a cutscene that begins the quest and key item Vial of dream incense.', sub = {
                { 'Windurst Waters Home Point #3 is just south of Kerutoto.' },
            } },
            { 'Head to Pso\'Xja Home Point #1.', sub = {
                { 'If you do not yet have the Home Point:', sub = {
                    { 'Travel to Beaucedine Glacier (H-8) and enter Pso\'Xja.', sub = {
                        { 'The Beaucedine Glacier Survival Guide brings you at H-9, just south of the entrance to Pso\'Xja.' },
                    } },
                    { 'Once inside the correct displacement sequence is red, purple, red, then purple; you will lose all buffs each time you go through the displacements.' },
                    { 'Take the elevator down, then head forward and head left at the intersection.' },
                    { 'Use the Stone Gate and select Yes when asked to use the Pso\'Xja passKey Item.' },
                    { 'The Home Point is just past the gate on the left.' },
                } },
            } },
            { 'Head down the steps into The Shrouded Maw.' },
            { 'Select the Memento Circle and pick Waking Dreams.' },
            { 'Defeat Diabolos Prime to receive a key item: Whisper of dreams.', sub = {
                { 'Diabolos Prime has the following spells and abilities:', sub = {
                    { 'Drain' },
                    { 'Aspir' },
                    { 'Sleepga II' },
                    { 'Dispelga' },
                    { 'Blindga' },
                    { 'Noctoshield- grants Diabolos the effect of "Phalanx."' },
                    { 'Dream Shroud- Enhances magic attack and magic defense of Diabolos.' },
                    { 'Camisado- Deals physical damage.' },
                    { 'Nether Blast- Delivers a ranged attack that deals darkness elemental damage.' },
                    { 'Ultimate Terror- Decreases attributes of players within area of effect.' },
                    { 'Nightmare- Deals darkness elemental damage that puts all enemies within the area of effect to sleep and gradually reduces their HP.' },
                    { 'Ruinous Omen- Astral Flow ability- Reduces the HP of enemies within the area of effect by a random percentage.' },
                } },
                { 'Tiles on the battlefield will vanish during the battle, dropping players to a Diremites-filled death.' },
            } },
            { 'Return to Kerutoto with the whisper and she will provide several reward options including the ability to summon Diabolos.' },
        },
    },
    ['Water Way to Go!'] = {
        title             = 'Water Way to Go!',
        starting_npc      = 'Ohbiru-Dohbiru, Windurst Waters (South) (J-9)',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'Ohbiru-Dohburu is running out of the Giddeus water needed to raise Fluoro-flora. He wants you to take a Rhinostery canteen to the springs at the back off Giddeus in order to refill his supply.',
        required_fame     = 'Windurst Fame Level: 3',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Canteen of Giddeus water',
        rewards           = '900 Gil',
        previous_quest    = 'Overnight Delivery',
        next_quest        = 'Blue Ribbon Blues',
        note              = 'This quest cannot be repeated if you have activated the quest Curses, Foiled A-Golem!?.',
        walkthrough       = {
            { 'Speak to Ohbiru-Dohbiru to receive a Rhinostery Canteen.' },
            { 'Trade the Rhinostery Canteen to the Giddeus Spring at (K-12) or (E-12) in Giddeus to receive a Canteen of Giddeus water.' },
            { 'Return to Ohbiru-Dohbiru and trade him the Canteen for your reward.' },
        },
    },
    ['Wild Card (Quest)'] = {
        title             = 'Wild Card (Quest)',
        starting_npc      = 'Honoi-Gomoi, Windurst Waters South (E-7)',
        subtitle          = 'Dream Dweller',
        repeatable        = 'No',
        description       = 'You have been asked to take apart the Joker Cardian and steal its Mana Orb. But... Where, o where has the Joker gone? O where, o where can he be?',
        required_fame     = 'Windurst Fame Level: 6',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Toraimarai Coffer Key',
        rewards           = '8,000 gil',
        previous_quest    = 'Crying Over Onions',
        next_quest        = 'The Promise',
        walkthrough       = {
            { 'Zone after finishing the previous quest.' },
            { 'Speak to Honoi-Gomoi to begin the quest.', sub = {
                { 'He is upstairs in his house, which is accessed through a back stairway.' },
            } },
            { 'Speak to Kohlo-Lakolo, Port Windurst (G-5).' },
            { 'Head to Windurst Walls (G-3) and check the door at the House of the Hero.', sub = {
                { 'Note who you talk to in this cinematic story experience.' },
            } },
            { 'Head to Toraimarai Canal (J-10) and open a Coffer there to obtain the Joker card.', sub = {
                { 'Picking the coffer as a Thief will work.' },
                { 'Various mobs in this zone drops the Toraimarai Coffer Key.' },
            } },
            { 'If you spoke to Joker during the previous cut-scene, return to to the House of the Hero for your reward.' },
            { 'If you spoke to Apururu, return to the Manustery in Windurst Woods (use Home Point #3).' },
            { 'Return to Honoi-Gomoi to complete the quest.' },
        },
    },
    ['Wonder Wands'] = {
        title             = 'Wonder Wands',
        starting_npc      = 'Hakkuru-Rinkuru, Port Windurst (E-7)',
        subtitle          = 'Doctor Shantotto\'s Guinea Pig',
        repeatable        = 'No',
        description       = 'The black, white, and red mage brigades of the War Warlocks are arguing over how the Orastery\'s budget should be spent. The captains of the three brigades each want you to obtain a sample of the wands they want so they can decide which to buy.',
        required_fame     = 'Windurst Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Mythril Rod, Rose Wand, Oak Staff',
        rewards           = 'New Moon Armlets 4800g',
        previous_quest    = 'Making Amens!',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Hakkuru-Rinkuru (Port Windurst, E-7 Orastery) to begin the quest.' },
            { 'Speak to the War Warlock Captains here in the Orastery.', sub = {
                { 'Ohruru is just south of Hakkuru-Rinkuru on the stage.' },
                { 'Goltata is against the wall to the west.' },
                { 'Yaman-Hachuman is against the wall to the northeast.' },
            } },
            { 'Obtain a Rose Wand, Oak Staff, and Mythril Rod. All three can be purchased using Sparks.', sub = {
                { 'Oak Staff and Mythril Rod are in the level 30-39 category.' },
                { 'Rose Wand is in the level 40-49 category.' },
            } },
            { 'Trade the Rose Wand, Oak Staff, and Mythril Rod to Hakkuru-Rinkuru for the cutscene that completes the quest.', sub = {
                { 'Two of the items will be returned to you at the end of the cutscene along with your reward and new title.' },
            } },
        },
    },
    ['Wondering Minstrel'] = {
        title             = 'Wondering Minstrel',
        starting_npc      = 'Jatan-Paratan, Windurst Waters North (F-10)',
        subtitle          = 'Down Piper Pipe-upperer',
        repeatable        = 'No',
        description       = 'The flutist Jatan-Paratan, who plays at the tavern, has lost his swing and now blows. It sounds as though a Hume bard who visited him lately is to blame, or maybe it\'s just a case of "bard luck"...?',
        required_fame     = 'Windurst Fame Level: 5',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Rosewood Lumber',
        rewards           = 'Faerie Piccolo',
        previous_quest    = 'None',
