    ['The Goblin Tailor'] = {
        title             = 'The Goblin Tailor',
        starting_npc      = 'Guttrix, Lower Jeuno (H-10)',
        subtitle          = 'Goblin\'s Exclusive Fashion Mannequin',
        repeatable        = 'Yes',
        description       = 'Each week, a different magical pattern appears inside a treasure chest somewhere. Give it to Guttrix and he\'ll reward you.',
        required_fame     = 'Jeuno Fame Level: 3',
        level_restriction = 'Level 10',
        pack              = 'None',
        requirements      = 'Ordelle Chest Key, or Gusgen Chest Key, or Shakhrami Chest Key',
        rewards           = 'Varies',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Guttrix, who will offer to make you Race Specific Equipment (RSE) if you bring him a Key Item Magical pattern.', sub = {
                { 'Key Item Magical patterns are found in Treasure Chests in Gusgen Mines, Ordelle\'s Caves, and Maze of Shakhrami.' },
                { 'You need to find the chests at the right time. Treasure maps for the zones are below (blue squares are chest spawns).' },
                { 'Alternately, adventurers in possession of the Key Item "Rhapsody in White" can purchase these keys for 2,500g from a Curio Vendor Moogle.' },
            } },
            { 'Each race is given a game week (Firesday to Darksday) to find a pattern. At the end of that game week, it will become the next race\'s turn.', sub = {
                { 'The race order is Hume Male → Hume Female → Elvaan Male → Elvaan Female → Tarutaru Male → Tarutaru Female → Mithra → Galka.' },
                { 'Each game week is 7 hours 40 minutes 48 seconds, meaning about every 8 hours the pattern changes.' },
                { 'The following sites provide RSE calendar details:', sub = {
                    { 'https://www.mithrapride.org/vana_time/' },
                    { 'https://www.pyogenes.com/ffxi/timer/v2.html' },
                } },
                { 'You must open the treasure chest when it is your race\'s week or you will not get the pattern.' },
                { 'You may only have one pattern on you at a time. However, there is no limit to the number of patterns you may re-obtain (as long as it is within your RSE week).' },
            } },
            { 'Turn the pattern into Guttrix, who will give you the option to craft it into one of the following four (4) armors:' },
        },
    },
