    ['The Road to Aht Urhgan'] = {
        title             = 'The Road to Aht Urhgan',
        starting_npc      = 'Faursel, Lower Jeuno (J-8)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'If you want to ride the mercenary transport ship from Mhaura, you must bring the required items to the Tenshodo.',
        required_fame     = 'Jeuno Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        requirements      = 'Tenshodo Membership',
        rewards           = 'Key Item Boarding permit Map of Wajaom Woodlands (Only if you take the 500,000 Gil route)',
        previous_quest    = 'None',
        next_quest        = 'None',
        note              = 'If you are on Rhapsodies of Vanadiel Mission 2-5, simply select "Where\'s Tenzen?" and you will get a Key Item Boarding permit for free.',
        walkthrough       = {
            { 'Talk to Faursel (Neptune\'s Spire J-8) for a cutscene.' },
            { 'He will give you three options to choose from. The third is a hidden option on the bottom. Choose the hidden option.' },
            { 'Talk to Faursel a second time for another cutscene and choose "I want to go".' },
            { 'Faursel will give you four ways to proceed: the Advanced path, the Intermediate path, the Beginner path, or paying 500,000 Gil.' },
            { 'Collect the required item(s) for Faursel. See the options below for your options.', sub = {
                { 'Tip! You can buy Coffer Keys from the Curio Moogle for 5,000 Gil if you have the Key Item "Rhapsody in Umber". If you have not progressed in Rhapsodies of Vana\'diel, now it is by far the easiest choice even though it is "Advanced".' },
            } },
            { 'Trade the requested item(s) to him. He will tell you to return tomorrow.' },
            { 'Zone and return to Lower Jeuno the next game day. Talk to Faursel again to obtain the Key Item Boarding permit.', sub = {
                { 'If you wish to skip obtaining the request items, you can pay him 500,000 Gil.', sub = {
                    { 'If you choose to pay the gil, you must change zones and return to Lower Jeuno the next game day. Then talk to Faursel and you will receive the Key Item Boarding permit and Map of Wajaom Woodlands and be teleported to the Leypoint in Wajaom Woodlands.' },
                } },
                { 'If you chose not to pay the gil, you are instructed to go to Mhaura and ride the Near East from the port to Al Zahbi.', sub = {
                    { 'If you have joined a Unity and have (or get) 100 Unity Accolades, you may skip the boat ride by using a Unity Warp with any Unity NPC -- But you must first obtain the Key Item Boarding permit to unlock the Aht Urghan warp options.', sub = {
                        { '125 Wajaom Woodlands option, and then chocobo/run to Al Zhabi, and then through there to Aht Urghan Whitegate.' },
                    } },
                } },
            } },
            { 'After completing this quest approach Naja Salaheem at Aht Urhgan Whitegate (I-10) to begin Aht Urhgan Mission 1: Land of Sacred Serpents.' },
        },
    },
