    ['VW Op. 118: Buburimu Squall'] = {
        title             = 'VW Op. 118: Buburimu Squall',
        starting_npc      = 'Mawl\'gofaur, Ru\'Lude Gardens',
        subtitle          = 'Botulus Rex Engorger',
