            { 'Enter Aydeewa Subterrane through the cave at (I-7) in Bhaflau Thickets.' },
            { 'Head to the room at (H-9) and begin mine in this room until you find one of three key items; Electrocell, Electropot, or Electrolocomotive.', sub = {
                { 'This is the same room where you finish the Blue Mage Flag Quest.' },
            } },
            { 'Return to Dkhaaya who will reward you with a Lightning Band.' },
            { 'At this point the quest is completed, however, if you trade the Lightning Band to the Leypoint at Wajaom Woodlands (G-8) it will transform into an Olduum Ring.' },
        },
    },
    ['Omens'] = {
        title             = 'Omens',
        starting_npc      = 'Waoud/Raubahn, Aht Urhgan Whitegate - (J-10)',
        subtitle          = 'Immortal Lion',
        repeatable        = 'Yes, after Memory reset',
        description       = 'The only choice you have left is to forge ahead in the quest for power, or face your own destruction... If ambition still fuels your soul, head to the Navukgo Execution Chamber and obliterate the monstrous flan!',
        required_fame     = 'Unknown',
        level_restriction = 'Level 50+ Blue Mage',
        pack              = 'Treasures of Aht Urhgan',
        requirements      = 'Key Item Sealed Immortal envelope',
        rewards           = 'Magus Charuqs',
        previous_quest    = 'Beginnings',
        next_quest        = 'Transformations',
        walkthrough       = {
            { '(Wait one in game day since completing the last quest and re-zone into Aht Urhgan Whitegate if you haven\'t already.)' },
            { 'Speak to Waoud to begin the quest.' },
            { 'Raubahn will direct you to find and kill a Flan in the Navukgo Execution Chamber.', sub = {
                { 'Travel via the Home Point in the part of Mount Zhayolm just outside the chamber or the Mount Zhayolm Unity warps (level 128 or 135) is quickest.' },
                { 'You do not have to be on Blue Mage to enter or complete this BCNM.' },
