    ['Burden of Suspicion'] = {
        title             = 'Burden of Suspicion',
        starting_npc      = 'Gentle Tiger, Bastok Markets (S) (H-6)',
        subtitle          = 'Assistant Detective',
        repeatable        = 'No',
        description       = 'It appears Senator Werner had a secret mercenary force in his employ. What other clandestine plans will be uncovered as the investigation continues...?',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Elixir',
        previous_quest    = 'Light in the Darkness',
        next_quest        = 'Storm on the Horizon',
        walkthrough       = {
            { 'Speak to Gentle Tiger (S) in Bastok Markets (S) at (H-6) for a cutscene that begins the quest.' },
            { 'Speak to Engelhart in Bastok Markets (S) at (K-10).' },
            { 'From Batallia Downs (S), use the (J-10) entrance to The Eldieme Necropolis (S).', sub = {
                { 'The quickest way is via Survival Guide to The Eldieme Necropolis (S).' },
                { 'Alternatively: via Voidwatch teleport (Jeuno I)' },
