    ['Lost in Translocation'] = {
        title             = 'Lost in Translocation',
        starting_npc      = 'Thorben - Batallia Downs (S) - (J-10)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Thorben has dropped his squad\'s map of Grauberg somewhere in Eldieme Necropolis. Find the map and return it to him.',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Map of Grauberg (If you do not already own it) 2,000 Experience Points 2,000 Gil',
