    ['Manifest Destiny'] = {
        title             = 'Manifest Destiny',
        starting_npc      = 'Dhea Prandoleh, Windurst Waters (S)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Having successfully turned back the Yagudo offensive, Lehko Habhoka and the Mithran mercenaries strike for Castle Oztroja to finish off their foe. The final conflict is nigh--report to the mercenary camp in the Meriphataud Mountains without delay!',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Dorter Key x3',
        rewards           = 'Hi-Reraiser',
        previous_quest    = 'Howl from the Heavens',
        next_quest        = 'At Journey\'s End',
        walkthrough       = {
            { 'Speak to Dhea Prandoleh for a cutscene.' },
            { 'Examine the Mithran Bivouac in Meriphataud Mountains (S) (I-8) for another cutscene.', sub = {
                { 'This is just NE of the Recall-Meriph telepoint.' },
            } },
            { 'Enter Castle Oztroja (S) for a cutscene.' },
            { 'Farm three Dorter Keys, which drop from Yagudo Eradicators, Yagudo Knights Templar, Yagudo Prioresses, and Yagudo Prelates found in Meriphataud Mountains (S) and inside Castle Oztroja (S).', sub = {
                { 'You will need this for all characters that wish to complete this mission.' },
            } },
            { 'Click the Iron Grilles located in the outside areas of the second floor of the castle (see maps) until you receive a message stating that you sense someone on the other side.' },
            { 'Trade the Dorter Keys to three of the Iron Grilles with prisoners trapped inside.', sub = {
                { 'Each key is lost when trading, so be sure to examine the Grille before hand. If you trade the key to an empty cell you will not get a cutscene, and the key will be lost.' },
                { 'Quest progress for freeing prisoners does not count towards other party member\'s progress.', sub = {
                    { 'There are two outdoor areas that hold prison cells. One located at E-7 and another at G-9' },
                } },
            } },
            { 'After freeing three sets of prisoners, you will obtain a Key ItemPoet god\'s key after the third cutscene.' },
            { 'Head to the top of Castle Oztroja (S) and check the Collapsing Floor for a cutscene.' },
            { 'Examine the Collapsing Floor again to enter a BCNM.' },
            { 'The fight is against Tzee Xicu the Manifest and 2x Air Elementals.', sub = {
                { 'Elementals cast Aeroga, Aeroga II, Silence, and Gravity' },
                { 'Tzee Xicu can use special TP move Kamitachi (full dispel and high damage, hate reset).' },
            } },
            { 'Defeat Tzee Xicu the Manifest to continue.', sub = {
                { 'If you lose the fight, you must return to the Mithran Bivouac to re-obtain the Key ItemPoet god\'s key.' },
                { 'If you win the fight but have a Hi-Reraiser in your inventory, you will be asked to pick up your reward at the Mithran Bivouac.' },
            } },
        },
    },
