    ['Provenance (Quest)'] = {
        title             = 'Provenance (Quest)',
        starting_npc      = 'N/A',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Mission Orders: A place from which all radiance once shone brightly forth now dimly flickers on the brink of existence... It is here that the source of Vana\'diel\'s suffering dwells, say the now multifarious caits.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'None',
        previous_quest    = 'Brace for the Unknown',
        next_quest        = 'Crystal Guardian',
        walkthrough       = {
            { 'Obtain the following three key items:', sub = {
                { 'Beguiling petrifact', sub = {
                    { 'Obtained for 330,000 cruor from a Voidwatch officer, rarely from any Zilart, City, or Jeuno path Voidwatch battle, or guaranteed from Beguiling Radiance.' },
                } },
                { 'Seductive petrifact', sub = {
                    { 'Obtained for 330,000 cruor from a Voidwatch officer, rarely from any Tavnazia, City, or Jeuno path Voidwatch battle, or guaranteed from Seductive Radiance.' },
                } },
                { 'Maddening petrifact', sub = {
