    ['The Forbidden Path'] = {
        title             = 'The Forbidden Path',
        starting_npc      = 'Lehko Habhoka, Windurst Waters (S)',
        subtitle          = 'Karaha-Baurha\'s Research Assistant',
        repeatable        = 'No',
        description       = 'In his secret laboratory deep beneath Windurst, the genius Karaha-Baruha pores over ancient tomes, that he might once again summon the Great Beast in his nation\'s time of need. Deliver what he seeks to Velda-Galda by the gate to Windurst Walls!',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Key ItemIrradiant strand Key ItemRefulgent strand Key ItemScintillant strand',
        rewards           = 'Stat potion depending on job',
        previous_quest    = 'The Long March North',
        next_quest        = 'Sins of the Mothers',
        walkthrough       = {
            { 'Zone into Windurst Waters (S) for a cutscene.', sub = {
                { 'Although the goal is to assemble the Key Item Gleipnir, you never actually obtain it.' },
            } },
            { 'You must now collect the following three key items in any order:', sub = {
                { 'Examine the Gate of Darkness in the Inner Horutoto Ruins (I-7, Rose Tower) [Map 4] for an Key Item Irradiant strand.', sub = {
                    { 'Survival Guide Toraimarai Canal would put you right next to Inner Horutoto Ruins zone.' },
                } },
                { 'Check the Fey Blossoms at Grauberg (S) (F-5) for a cutscene', sub = {
                    { 'Check again and you will be asked for a Bottled Pixie' },
                    { 'Obtain a Bottled Pixie and trade it to the Fey Blossoms in Grauberg (S) (F-5, between 18:00-6:00) to obtain a Key Item Scintillant strand from Adrasteia.', sub = {
                        { 'The Bottled Pixie is a guaranteed drop from Yagudo High Priest – right at the Survival Guide for Meriphataud Mountains (S), or just within Castle Oztroja (S) for additional spawn points.' },
                        { 'You can get to the Witchfire Glen area either by traversing Grauberg directly, or more quickly by using a route through the Veridical Conflux through part of the Walk of Echoes that connects to near Pashhow gate crystal if sufficient mission and Jeuno Voidwatch Questline progress has been made – use the nearby Survival Guide or Recall-Pashh.' },
                    } },
                } },
                { 'Head to Castle Oztroja (S) and examine the Writhing Flame (G-7, ground floor, in the north hallway, head north from the large central room) for a cutscene.', sub = {
                    { 'Return to the Writhing Flame and trade it any Job Testimony for a Key Item Refulgent strand. Testimony does not have to match your job.', sub = {
                        { 'Scholar\'s Testimony is a high drop rate from 3 of the 4 Orcs at I-11 west of the East Ronfaure [S] Survival Guide' },
                    } },
                    { 'Note: You will be unable to complete this miniquest on GEO or RUN.' },
                } },
            } },
            { 'Speak to Velda-Galda at Windurst Waters (S) (K-9) three times.', sub = {
                { 'Each key item turn-in generates a separate cutscene.' },
            } },
            { 'Wait one game day before speaking to Velda-Galda again for the final cutscene.' },
        },
    },
    ['The Fumbling Friar'] = {
        title             = 'The Fumbling Friar',
        starting_npc      = 'Fondactiont, Garlaige Citadel (S) (I-6)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Fondactiont wants you to find and bring back an important package that he "dropped" into the river in Grauberg.',
