    ['The Long March North'] = {
        title             = 'The Long March North',
        starting_npc      = 'Robel-Akbel, Windurst Waters (S)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Battered but not beaten, the Windurstian army steels itself for a grueling march north. The first leg of the journey takes you to San d\'Oria, where you and your Cobra companions will learn what trouble lies brewing on the Valdeaunian front.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Stellar Earring',
        previous_quest    = 'A Feast for Gnats',
        next_quest        = 'The Forbidden Path',
        walkthrough       = {
            { 'Zone into Windurst Waters (S) for a cutscene.' },
            { 'Go to Southern San d\'Oria (S) and talk to Raustigne (I-7) for a cutscene.', sub = {
                { 'Lehko Habhoka mentions the need for Key Item Darkfire cinders and Key Item Floelight stones, although you will not obtain the latter.' },
            } },
            { 'Talk to Hauberliond (H-9) for a cutscene.' },
            { 'Depending on your answers, you will be instructed to find New-turned Earth in one of three zones:', sub = {
                { 'East Ronfaure (S) at (J-11), this is near the Survival Guide.' },
                { 'La Vaule (S) at (K-9).', sub = {
                    { 'On the rock between the hut and the wooden stable. They may not appear if there is a campaign there. If you cannot see it, sign up and butcher the campaign enemies so they leave.' },
                    { 'This appears to be the result if you choose the top answers only.' },
                } },
                { 'Jugner Forest (S) at (J-5) (near Batallia Downs (S)\'s Survival Guide).' },
            } },
            { 'Check the New-turned Earth for a cutscene and Key ItemDarkfire Cinder.' },
            { 'Head to the Metalworks Gunpowder Room (present day) and talk to Striking Snake (H-7) for a cutscene.' },
            { 'Grab some pickaxes.' },
            { 'Head to North Gustaberg (S) locate Mining points to obtain Key ItemLiquid Quicksilver and Key ItemGelid Sulfur.', sub = {
                { 'It\'s possible to get both from the same Mining Point.' },
            } },
            { 'Return to Striking Snake with both key items for a brief cutscene.', sub = {
                { 'You must now wait 1 game day and change zones.' },
            } },
            { 'Talk to Striking Snake after zoning and waiting 1 game day to receive Key ItemBeastbane Bullets.' },
            { 'Head to Fort Karugo-Narugo (S) and talk to Rotih Moalghett (I-8) on map 2 for a cutscene.' },
            { 'Head to (E/F-7) and examine the Warding Door to start a fight.', sub = {
                { 'Note: The battle will begin as soon as you click on the door; there is no cutscene.' },
                { 'There is a 30 minute time limit for this fight.' },
                { 'The battle is against 5 monsters:', sub = {
                    { 'Count Furfur: Appears to be a Dark Knight.' },
                    { 'Count Murmur x2: Appear to be Warriors.' },
                    { 'Tartalo x2 (Ahriman): Appear to be Black Mages and love to cast -ga spells including Sleepga.' },
                } },
                { 'Up to 6 people in one party may participate at once in this battle.' },
                { 'Fight is trivial for any character at level 99.' },
            } },
            { 'Once the monsters are defeated, check the Warding Door again at (E/F-7) for a final cutscene and Stellar Earring.', sub = {
                { 'If your inventory is full, check the Warding Door again for your reward. The cutscene will not be replayed.' },
            } },
        },
    },
    ['The Lost Book'] = {
        title             = 'The Lost Book',
        starting_npc      = 'Yoran-Oran, Windurst Waters (S) (J-9) (Rhinostery)',
        subtitle          = 'None',
