    ['The Price of Valor'] = {
        title             = 'The Price of Valor',
        starting_npc      = 'Rahal, Jugner Forest (S)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Bloodwing Horde military tactician, Zogbog, has made bold claims that he holds the key to nullifying Tavnazia\'s impenetrable defensive walls. Help the Swiftwing Griffins in their risk-ridden mission to uncover the nature of his latest plot.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Multiple Hatchets, for logging.',
        rewards           = 'Peiste Skin',
        previous_quest    = 'In a Haze of Glory',
        next_quest        = 'Bonds That Never Die',
        walkthrough       = {
            { 'You must zone and wait one game day after completing In a Haze of Glory in order to start this quest.' },
            { 'Speak to Rholont (E-7) in Southern San d\'Oria (S) for a cutscene.' },
            { 'Gather the following three Key Item key items:', sub = {
                { 'Key Item Ronfaure maple syrup: obtained randomly by logging in East Ronfaure (S).', sub = {
                    { 'The next quest also requires logging, therefore it\'s recommended to purchase multiple Hatchets.' },
                } },
                { 'Key Item Long-life biscuits: obtained by examining the Tree Hollow directly behind Rholont.' },
                { 'Key Item Flask of Kingdom water: obtained by examining the Well east of Rholont.' },
            } },
            { 'Speak to Rholont to receive the Key Item Biscuit a la Rholont.' },
            { 'Go to Jugner Forest (S) and examine the Felled Trees at western (G-7). Use the Campaign warp.', sub = {
                { 'Fastest way to get here is to Recall-Jugner; if that\'s not available, run North then NW from the Jugner Forest (S) Survival Guide warp.' },
            } },
            { 'Go to Vunkerl Inlet (S) (the Campaign warp is closer than the Survival Guide to your first destination) and examine two Toppled Cressets in the correct order:', sub = {
                { 'First, examine the Toppled Cresset at (I-8) for a short cutscene leading you west.' },
                { 'Next, examine the second Toppled Cresset at (F-9)/(F-8) for another short cutscene leading you south.' },
            } },
            { 'Examine the Underbrush at (F-13) for a third cutscene. Examine it again to spawn Madthrasher Zradbodd.', sub = {
                { 'Madthrasher Zradbodd is an Orc BLM who has a large amount of Fastcast. He likes to spam Tier IV elemental and tier III elemental -ga spells, as well as Sleepga and Dispellga.' },
                { 'Having a Blue Mage to stun the area of effect spells is very handy if you\'re below i119.' },
            } },
            { 'After defeating Madthrasher Zradbodd, check the Underbrush again for a message telling you to go to Pashhow Marshlands (S).', sub = {
                { 'You will have to defeat the NM again if you zone without getting this message!' },
            } },
            { 'Go to Pashhow Marshlands (S) at (G-6) and examine the Shimmering Pondweed for a cutscene that completes the quest.', sub = {
                { 'The spot you are looking for within (G-6) will be in the northwest corner of the grid.', sub = {
                    { 'Using the Campaign teleport will most likely be your fastest way here.' },
                    { 'The next closest method is teleporting to the Survival Guide in Rolanberry Fields (S), which will put you right at the top zone line for Pashhow Marshlands (S).' },
                } },
            } },
        },
    },
    ['The Swarm'] = {
        title             = 'The Swarm',
        starting_npc      = 'Rolanberry Fields (S) (D-9) Fortilace',
        subtitle          = 'Swarminator',
        repeatable        = 'Yes',
        description       = 'A vermin infestation of unprecedented scale has broken out within the mines, severely disrupting mining operations and causing considerable financial loss to the industry. The Silvermines Pest Control Committee is urgently recruiting dauntless individuals to aid in their extermination. Items found within the premises can be utilized at your discretion.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Pest Repellent',
        rewards           = 'Swarminator Title',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Note: This quest only appears as an available quest upon use of the Pest Repellent. It does not appear in the completed quest log section upon completion of the quest.' },
            { 'Obtain a Pest Repellent from the various FFXI events held throughout the year.' },
            { 'Have the leader use the Pest Repellent and then check the Fortilace (D-9) Rolanberry Fields (S) to initiate the battle.', sub = {
                { 'Minimum of 3 players required.' },
                { 'Does not work for alliance members, only members of the leader\'s party may enter.' },
                { 'All players located in the zone will be warped into the battlefield.' },
            } },
            { 'An initial minute allows you to buff up before "contact made" is noted in the log.' },
            { '5 minute time limit to battle an endless swarm of various monsters.', sub = {
                { 'The Swarmspawn monsters fall from where you enter from the ceiling and then begin to walk away and do not respond to actions against them.' },
                { 'As such, an optimal method to deal with them is AoE spells centered around the caster, such as BLM/GEO/BLU.' },
                { 'A well-geared nuking GEO can one-shot using tier-1 AoE spells (Fira, Aera, etc.) and achieve "Swarm Chain" 200+' },
                { 'Occasionally, the party will be rewarded with HP or TP boosts.' },
            } },
            { 'Players are scored and ranked by the amount and types of monsters they defeat individually, not as a group.', sub = {
                { 'This has no effect on the outcome of the battle.' },
                { 'Certain mobs are worth more than others, from 100-300, but also spikes up to almost 4000 (Adamantoise mobs perhaps?)' },
            } },
            { 'Players are rewarded with the title of "Swarminator".' },
        },
    },
