    ['The Truth Lies Hid'] = {
        title             = 'The Truth Lies Hid',
        starting_npc      = 'Gentle Tiger, Bastok Markets (S) (H-6)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Klara Bester, erstwhile captain of the Mythril Musketeers turned fugitive, has ensconced herself deep in the heart of Castle Zvahl. You must infiltrate the enemy stronghold with your comrades and uncover the truth behind your ex-commander\'s treachery.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Elixir',
        rewards           = 'Sanctus Rosary',
        previous_quest    = 'What Price Loyalty',
        next_quest        = 'Bonds of Mythril',
        walkthrough       = {
            { 'Obtain an Elixir from the Curio Moogle or Auction House.' },
            { 'Speak to Gentle Tiger in Bastok Markets (S) at (H-6) to begin the quest.' },
            { 'Enter Castle Zvahl Baileys (S) for a cutscene.' },
            { 'In Castle Zvahl Keep (S), there are three Imp NPCs.', sub = {
                { 'Rikke is the northwest Imp at (G-7) on the first map.' },
                { 'Rakke is the southwest Imp at (G-10) on the first map.' },
                { 'Rokke is the southeast Imp at (H-10) on the first map.' },
            } },
            { 'Speak to all three imps, they will each demand an Elixir. Your goal is to determine which one is telling the truth.', sub = {
                { 'You do not need to trade the Elixir to make them talk, you only trade it when you know which to give it to.' },
                { 'Each Imp will make a statement regarding another imp being honest or dishonest. Pay close attention to the line(s) immediately after the Elixir request.' },
                { 'You don\'t need to speak to all three imps (but you may be forced to). It is possible to deduce the correct imp from talking to just one or two.' },
                { 'See the Discussion page for detailed answers.' },
            } },
        },
    },
    ['The Weekly Adventurer'] = {
        title             = 'The Weekly Adventurer',
        starting_npc      = 'Naiko-Paneiko - Crawlers\' Nest (S) (L-8)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Battlefield journalist Naiko-Paneiko has received intriguing leads concerning the appearance of a monster in the Rolanberry Fields. Go nab the scoop!',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Map of Fort Karugo-Narugo (If you do not already own it) 2,000 Experience Points 2,000 Gil',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Begin quest by speaking with Naiko-Paneiko, just inside the entrance of Crawlers\' Nest (S) at (L-8) (when you enter from Rolanberry Fields (S)). He will give you a Key Item Scoop-Dedicated Linkpearl.' },
            { 'Go to (G-9) in Rolanberry Fields (S) and talk to Rakula-Motakula, who is upon a ballista up the hill, behind the long fence.' },
            { 'When prompted, talk about the Mandragoras.' },
            { 'He will ask you 3 questions, how many leafed mandies there are, then how many black mandies, and finally how many flowered mandies there are. The answer is 4, 4, and 5.' },
            { 'Head back to Naiko-Paneiko for your reward.' },
        },
    },
    ['The Young and the Threadless'] = {
        title             = 'The Young and the Threadless',
        starting_npc      = 'Ponono (S), Windurst Waters (S) (K-11) (North Map)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Unable to keep up with the overwhelming demand for her custom charm bracelets, the Windurstian clothcrafter Ponono has entrusted you with procuring a fresh supply of enchanted thread.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Trainee Scissors',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Talk to Ponono (S) at Windurst Waters (S) (K-11, North Map - Residential Area) to obtain the Key Item: Ponono\'s charm.' },
            { 'Zone and speak to Ponono again.' },
            { 'Ponono will give you three key items, you will need to go to the following bodies of water and examine them to get new key items.' },
        },
    },
    ['Third Tour of Duchy'] = {
        title             = 'Third Tour of Duchy',
        starting_npc      = 'N/A',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Mission Orders: The Duchy has requested your presence yet again. Wherever have the Voidwalkers struck this time? In any event, make haste to the palace in Ru\'Lude Gardens or the main gate in Sauromugue Champaign for further orders.',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'None',
        previous_quest    = 'A Farewell to Felines',
        next_quest        = 'Glimmer of Hope',
        walkthrough       = {
            { 'Proceed to the Audience Chamber in Ru\'Lude Gardens or the Bulwark Gate in Sauromugue Champaign (S) for a cutscene which ends this quest and begins the following quest.' },
        },
    },
    ['VW Op. 126: Qufim Incursion'] = {
        title             = 'VW Op. 126: Qufim Incursion',
        starting_npc      = 'N/A',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Mission Orders: The Voidwalker presence grows ever stronger at Qufim Island, Behemoth\'s Dominion, and Delkfutt\'s Tower. Lure out and eliminate hostiles to secure the area.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = '50,000 Gil',
        previous_quest    = 'Battle on a New Front',
        next_quest        = 'A Cait Calls',
        note              = 'If you cannot obtain the Key Item Voidwatch alarum: First check the Bulwark Gate in Sauromugue Champaign (S) for the cutscene that awards 30,000 Gil. Look at the following Quest and head to Pashhow Marshlands (S) for a cutscene before talking to the Officers. Return to the Audience Chamber in Ru\'Lude Gardens for a cutscene and to receive 50,000 Gil. The next Quest will automatically be flagged upon completion. Retrieved from "https://www.bg-wiki.com/index.php?title=VW_Op._126:_Qufim_Incursion&oldid=728133" window[\'nitroAds\'].createAd(\'bgwiki-anchor\', { "refreshLimit": 0, "refreshTime": 30, "format": "anchor", "anchor": "bottom", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-right" },  "mediaQuery": "(min-width: 0px)" }); window[\'nitroAds\'].createAd(\'nitro-video\', { "refreshTime": 30, "format": "floating", "report": { "enabled": true, "icon": true, "wording": "Report Ad", "position": "top-left" } }); Categories: QuestsCrystal War QuestsVoidwatch QuestsFFXI Wiki',
        walkthrough       = {
            { 'After completing Battle on a New Front and obtaining Key Item White stratum abyssite III, engage in and complete the 3 Tier III Voidwatch battles in the Qufim region:', sub = {
                { 'Kaggen - Qufim Island (G-6), (H-6), (I-7).' },
                { 'Akvan - Lower Delkfutt\'s Tower Basement (G-9), Floor 2 (F-5/6) and Floor 3 (I-6).' },
                { 'Pil - Behemoth\'s Dominion (E-7), (H-8), (J-10).' },
            } },
            { 'Speak with any Voidwatch Officer in PRESENT DAY! to receive the Key Item Key Item Voidwatch alarum.', sub = {
                { 'Note: If you cannot obtain the Key Item Voidwatch alarum:' },
                { 'First check the Bulwark Gate in Sauromugue Champaign (S) for the cutscene that awards 30,000 Gil.' },
                { 'Look at the following Quest and head to Pashhow Marshlands (S) for a cutscene before talking to the Officers.' },
            } },
            { 'Return to the Audience Chamber in Ru\'Lude Gardens for a cutscene and to receive 50,000 Gil. The next Quest will automatically be flagged upon completion.' },
        },
    },
    ['What Price Loyalty'] = {
        title             = 'What Price Loyalty',
        starting_npc      = 'Gentle Tiger, Bastok Markets (S) (H-6)',
        subtitle          = 'Presidential Protector',
        repeatable        = 'No',
        description       = 'Apprehended in Beaucedine after deserting his unit, Zeid awaits punishment in a dark cell of Benedikt Watchtower. Can nothing be done to save him from his fate? At his friend Gentle Tiger\'s behest, you travel to North Gustaberg to offer your aid.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Fourth Staff',
        previous_quest    = 'Beneath the Mask',
        next_quest        = 'The Truth Lies Hid',
        walkthrough       = {
            { 'Speak to Gentle Tiger in Bastok Markets (S) - (H-6) to begin the quest and to receive the Key ItemSack of victuals.' },
            { 'Head to the Benedikt Watchtower in North Gustaberg (S) at (E-11) and speak to Roderich.', sub = {
                { 'Use the Campaign Arbiters to reach this tower quickly, then go east, as it is nearby.' },
            } },
            { 'Speak to Gentle Tiger.' },
            { 'Travel to Xarcabard (S) for a cutscene and your Key ItemCommander\'s endorsement.' },
            { 'Examine the Forbidding Portal at the North West Corner of (I-7) for a cutscene. Examine it again to enter the battlefield.', sub = {
                { 'Trusts may be used in this fight.' },
                { 'Any job with item level 119 equipment should have no trouble clearing the fight.' },
                { 'When entering, you will fight one humanoid who uses all sword weapon skills, frequently double attacks, and uses Mighty Strikes at 50%.' },
                { 'Your opponent will randomly select a player and that player will lose all enmity.' },
                { 'Magic spells (especially nukes and enhancing magic) seem to gain disproportionate enmity in this battle.' },
                { 'At approximately 50% your opponent will do a monster two-hour animation and gain access to a new AoE weapon skill named Temblor Blade with the additional effect of petrify.' },
                { 'Should you lose this battle, speak to Gentle Tiger for another Key ItemCommander\'s endorsement.' },
            } },
            { 'Speak to Gentle Tiger for a cutscene and your reward.' },
        },
    },
    ['When One Man Is Not Enough'] = {
        title             = 'When One Man Is Not Enough',
        starting_npc      = 'Dhea Prandoleh, Windurst Waters (S) - (H-10)',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'The Mithran mercenary majors are feuding over exclusive rights to Lehko Habhoka who is now presumed to be hiding out in Sarutabaruta. Find and bring back the heartthrob before things get out of hand.',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        requirements      = 'Blackened Siredon, Forest Carp, Greedie, or Pipira',
        rewards           = '12 x Red Rose',
        previous_quest    = 'A Manifest Problem',
        next_quest        = 'A Feast for Gnats',
        walkthrough       = {
            { 'Note: Several fish are noted in this mission: Blackened Siredon, Forest Carp, Greedie, and Pipira. You will need to obtain at least one of these fish to complete this mission. It is suggested to obtain one from the Auction House or some other means before going to Windurst Waters (S). Which fish you end up using does affect the cutscene received (see below) but the end result of progressing is the same.' },
        },
    },
    ['Wrath of the Griffon'] = {
        title             = 'Wrath of the Griffon',
        starting_npc      = 'Rholont, Southern San d\'Oria (S) (E-7)',
        subtitle          = 'Fine Young Griffon',
        repeatable        = 'No',
        description       = 'Squire Altennia has been captured by Orcs, and is being held at their encampment in southern Jugner Forest. Rescue her before it\'s too late!',
        required_fame     = 'Unknown',
        level_restriction = 'None',
        pack              = 'Wings of the Goddess',
        rewards           = 'Key ItemMilitary scrip',
        previous_quest    = 'Boy and the Beast',
        next_quest        = 'Perils of the Griffon',
        walkthrough       = {
            { 'Speak with Rholont (E-7) in Southern San d\'Oria (S) to begin the quest.' },
            { 'Head to (H-10) in Jugner Forest (S) (at the foot of one of the watch platforms), to find a ???.', sub = {
                { 'Survival Guide teleport to Jugner Forest (S) is the fastest way. (If you do not have it, grab it on this mission as you will need it in another WotG mission very soon)' },
                { 'You may want to grab the Recall-Jugner KI too.' },
            } },
            { 'After the cutscene, prepare yourself for a NM fight.' },
            { 'Touch the ??? again to pop Cobraclaw Buchzvotch.' },
            { 'After defeating Cobraclaw Buchzvotch, click the ??? again for another cutscene.' },
            { 'Return to Rholont to complete the quest and obtain a Key ItemMilitary Scrip.', sub = {
                { 'Wyatt (L-6) in Southern San d\'Oria (S) will exchange your reward for 20,147 gil.' },
            } },
        },
    },
}

quest_info['outlands'] = {
    ['20 in Pirate Years'] = {
