        level_restriction = 'Level 50+ Samurai',
        pack              = 'Rise of the Zilart',
        requirements      = 'Gold Thread',
        rewards           = 'Myochin Kabuto',
        previous_quest    = 'Yomi Okuri',
        next_quest        = 'None',
        walkthrough       = {
