    ['Luck of the Draw'] = {
        title             = 'Luck of the Draw',
        starting_npc      = 'Ratihb, Aht Urhgan Whitegate (J-12)',
        subtitle          = 'Seagull Phratrie Crew Member',
        repeatable        = 'No',
        description       = 'Ratihb wants you to check on his son Wasuhd, who has gone in search of his older brother.',
        required_fame     = 'Aht Urhgan Fame Level: Unknown',
        level_restriction = 'Level 30+ (Any job)',
        pack              = 'Treasures of Aht Urhgan',
        requirements      = 'Must be on a job that is level 30 or higher.',
        rewards           = 'Corsair Die Ability to become a Corsair.',
        previous_quest    = 'None',
        next_quest        = 'Equipped for All Occasions',
        walkthrough       = {
            { 'Speak to Ratihb at Aht Urhgan Whitegate (J-12 Shararat Teahouse) for a cutscene that begins the quest.' },
            { 'Speak to Mafwahb at Aht Urhgan Whitegate (L-9 Palace Door) for a cutscene.' },
            { 'Go to Arrapago Reef Map 1.', sub = {
                { 'The Survival Guide to Arrapago Reef is the fastest way.' },
                { 'If you need to walk:', sub = {
                    { 'Take the North exit from Nashmau to Caedarva Mire.' },
                    { 'Travel to Caedarva Mire (I-6) and enter Arrapago Reef.' },
                } },
            } },
            { 'Click on the ??? (NOT the shining spot labeled "-") at the North East corner of (H-10) for a cutscene. It\'s located on a ship. To proceed there, you will need a Lamian Fang Key.', sub = {
                { 'It\'s possible to get a different cutscene that starts with Zweeha upon clicking the ???. Clicking the ??? may also direct you to investigate a pier to the northwest. If this happens, keep clicking until you get the correct cutscene that starts with Wasuhd and Mutihb before proceeding to the next step.' },
                { 'Lamian Fang Keys drop from Lamiae and Draugers in the area.' },
                { 'Enemies that can drop the key have approx ~16 minute repop window, so consider this before setting out. There are a limited number of potential opponents (5) between the zone-line and the gate before the quest marker.' },
                { 'You can also receive a Lamian Fang Key from a ??? spot in Caedarva Mire (I-7) Map 1 (southern part of the block). You can obtain a new key from there once every game day.', sub = {
                    { 'To get to the ??? spot, you must use the Lamian Fang Key on the Iron Gate at (J-10), then go immediately west on the small map to another Iron Gate. (This Iron Gate is unlocked.)' },
                    { 'The Survival Guide in Arrapago Reef is very near to the Iron Gate.' },
                } },
            } },
            { 'Enter Talacca Cove from Caedarva Mire (E-9) Map 1. This area is outside of Nashmau\'s west exit.', sub = {
                { 'Home Point #1 in Caedarva Mire puts you right at this zone.' },
            } },
            { 'Go around the left side of the lake in the large room until you find a ??? spot and examine it for a cutscene and the key item Forgotten hexagun.', sub = {
                { 'The ??? is not next to the water, it is at the NW corner, on a rock, close to the tunnel entrance going West.' },
            } },
            { 'Travel west into the tunnel entrance, then North to find the Rock Slab (follow the tunnel, you can\'t go wrong), examine the slab for a cutscene that ends the quest to receive your reward.' },
        },
    },
