quest_info['abyssea'] = {
    ['A Beaked Blusterer'] = {
        title             = 'A Beaked Blusterer',
        starting_npc      = 'Orgis, South Gustaberg',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'A fiendish roc, capable of kicking up flesh-rending winds in its wake, is the bane of the bedraggled survivors of Abyssea - Altepa. Can this feathery storm of death be stilled, and the people given the chance to pick up the pieces?',
        required_fame     = 'Abyssea - Altepa Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'Key Item Lunar/Ivory Abyssite, see chart below.',
        previous_quest    = 'Dawn of Death',
        next_quest        = 'Heroes of Abyssea (Quest)',
        walkthrough       = {
            { 'Examine the Cavernous Maw in South Gustaberg at (J-10) while in possession of a Key Item Traverser stone. You will receive a cutscene with Orgis.' },
            { 'Defeat the Notorious Monster Bennu.', sub = {
                { 'Refer to the Abyssea - Altepa page for the flowchart for details on spawning this monster.' },
