    ['A Journey Begins'] = {
        title             = 'A Journey Begins',
        starting_npc      = 'N/A',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'How is it possible that no one else noticed the mysterious flash of light that lit up the skies of Port Jeuno? A man calling himself Joachim claims to know the answer...',
        required_fame     = 'Abyssea Fame Level: 1',
        level_restriction = 'Level 30',
