    ['A Mightier Martello (Altepa)'] = {
        title             = 'A Mightier Martello (Altepa)',
        starting_npc      = 'Machine Outfitter (Altepa), Abyssea - Altepa',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'Upgrading the fuel capacity of the martellos in the Altepa Desert will mean less frequent replenishment runs, easing the burden on Resistance troops in the area. Install a fuel reservoir in a martello, and return the excess parts to the machine outfitter when the job is done.',
        required_fame     = 'Abyssea - Altepa Fame Level: 3',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'Varying amount of Cruor depending on the direction the upgrade is completed from.',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to the Machine Outfitter (Altepa) near the entrance of zone, and choose "Assist with upgrades" to accept the quest.', sub = {
                { 'You will obtain a Key Item Fuel reservoir.' },
                { 'You cannot zone at any point during the quest, or you lose the key item and you must restart.' },
            } },
            { 'Find a Martello in the zone. They are usually around the various Confluxes, or you can see a list on the Martello page.', sub = {
                { 'It is possible to upgrade it even if it is already at 100%.' },
            } },
            { 'Click on "Prepare to upgrade martello" in the menu once you interact with one, then confirm.' },
            { 'The log will tell you a direction to stand in order to upgrade the device, but the menu will tell you a different direction. Best results are achieve by following the direction in the menu.', sub = {
                { 'Although it is not in the log, the Key Item Fuel reservoir will be replaced with the Key Item Cracked fuel reservoir.' },
            } },
            { 'Return to the Machine Outfitter (Altepa) to complete the quest.' },
        },
    },
