    ['Brygid the Stylist Strikes Back'] = {
        title             = 'Brygid the Stylist Strikes Back',
        starting_npc      = 'Brygid (A) (D-11), Abyssea - Altepa',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'Brygid, the self-professed stylist extraordinaire, has given you some fashion advice. Her pull-no-punches style of fashion critiques seems somehow familiar...',
