    ['Desert Rain I (Attohwa)'] = {
        title             = 'Desert Rain I (Attohwa)',
        starting_npc      = 'Resistance Sapper (Attohwa) (F-9), Abyssea - Attohwa',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'The continual defense of the pulse martello has pushed our soldiers to the brink of exhaustion. This operation requires you to transport ensorceled battle provisions from the stockpile, using the enchanted sack provided. Be mindful that the sack does not rupture in the process.',
        required_fame     = 'Abyssea - Attohwa Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'Varying amount of Cruor and Resistance Credits 0~1 of: any Empyrean Armor +1 Head seals',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to the Resistance Sapper (Attohwa) at (F-9) (Veridical Conflux #00) and to begin the quest.' },
            { 'A spot on the map will be marked with a Target marker, and you will receive a Key Item Magicked flaxen sack.' },
            { 'Travel to the spot marked on your map.', sub = {
                { 'Veridical Conflux #06 is nearby.' },
            } },
            { 'Interact with the smaller Repair Trunk and begin filling your bag.', sub = {
                { 'There are three types of items: oil cloth, triangular flask, and elongated flask. The more you pack, the more rewards you get, but if you pack too much it will tear and you will fail the quest. Statuses of the sack varies from "perfect condition", "feels a little bit taunt", "showing signs of stretching", and "squeaking under tension".' },
            } },
            { 'When you are satisfied with your bag, "Finish cramming" and head back to the Resistance Sapper (Attohwa) to finish the quest.', sub = {
                { 'The amount of Cruor and Resistance Credits you receive depend on how much your cram in the bag.', sub = {
                    { 'The chance at a seal is the same regardless of how much cramming was done.' },
                } },
            } },
        },
    },
