    ['Rose on the Heath'] = {
        title             = 'Rose on the Heath',
        starting_npc      = 'Ayame (A) (I-13), Abyssea - Konschtat',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'The latest incursion of Abyssean fiends has left shattered linkshells in its wake, severing precious lines of communication between Captain Ayame and her comrades afield. Deliver three linkpearls, one each to Captains Rashid, Argus, and Helga, before an ill fate befalls these brave warriors of the resistance!',
        required_fame     = 'Abyssea - Konschtat Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = '400 Cruor',
        previous_quest    = 'Of Malnourished Martellos',
        next_quest        = 'Full-of-Himself Alchemist Shady Business Redux The Soul of the Matter',
        walkthrough       = {
            { 'Speak to Ayame (A) at (I-13) to begin the quest. You will receive the following:', sub = {
                { 'Key Item Captain Rashid\'s linkpearl' },
                { 'Key Item Captain Argus\'s linkpearl' },
                { 'Key Item Captain Helga\'s linkpearl' },
                { 'Key Item Seal of the resistance.' },
            } },
            { 'Speak to Argus (A) at (D-7) - Conflux #03, then walk north/east.' },
            { 'Speak to Helga (A) at (G-5) - Conflux #05, then walk north through the Mesa Wivre.' },
            { 'Speak to Rashid (A) at (F-10) - Conflux #02, then walk northwest.' },
            { 'Return to Ayame (A) to complete the quest. She will take the Key Item Seal of the resistance back from you.' },
        },
    },
    ['Savory Salvation'] = {
        title             = 'Savory Salvation',
        starting_npc      = 'Piketo-Puketo (A) (F-9), Abyssea - Tahrongi',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'A culinarian with serious delusions of grandeur sees himself as the savior of his nation\'s people. Employ the fertilizer he\'s given you on a suitable tree and bring back anything edible that may grow.',
        required_fame     = 'Abyssea - Tahrongi Fame Level: 2',
        level_restriction = 'None',
        pack              = 'Abyssea',
        requirements      = 'Key Item Tahrongi tree nut',
        rewards           = '200 Cruor',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Piketo-Puketo (A) in the Western Encampment at (F-9). Veridical Conflux #03 is nearby.', sub = {
                { 'He\'ll give you Key Item Vial of flower-wower fertilizer.' },
