        walkthrough       = {
            { 'Speak to Helga (A) at (G-5), southeast of Veridical Conflux #06 to begin the quest.' },
            { 'Speak to Naji (A) at (J-5). He will give you Key Item Naji\'s gauger plate.', sub = {
                { 'To get here the quickest, use Veridical Conflux #08, then head southwest while hugging the left cliff.', sub = {
