    ['Sisters in Crime'] = {
        title             = 'Sisters in Crime',
        starting_npc      = 'Cha Lebagta (A) and Bopa Greso (A) (I-10), Abyssea - Tahrongi',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'Holding out hope that their disreputable band may yet be reunited, the two lackeys of the Cat Burglar have co-opted you to spread the news of their survival. Affix the ridiculous posters they\'ve given you to the signposts in the canyon.',
