    ['Slacking Subordinates'] = {
        title             = 'Slacking Subordinates',
        starting_npc      = 'Chumimi (A) (G-7), Abyssea - Altepa',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'Chumimi\'s good-for-nothing assistants Chemioue, Biggorf, and Tapoh Lihzeh still haven\'t done their homework. Hunt them down and relay their findings to Chumimi by any means necessary.',
        required_fame     = 'Abyssea - Altepa Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'First time completion: 400~500 Cruor Subsequent completions: 150~250 Cruor Chance at one of the following Empyrean Armor +1 Body seals (ONLY if you do well with the quest): Mavi Seal: Body (BLU) Estoqueur\'s Seal: Body (RDM) Sylvan Seal: Body (RNG) Cirque Seal: Body (PUP) Ravager\'s Seal: Body (WAR)',
        previous_quest    = 'The Titus Touch',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Chumimi (A) at (G-7) (east of Conflux 7 at the Revelation Rock oasis) to start the quest.' },
            { 'You must talk to all 3 of the following NPCs for this quest:', sub = {
                { 'Biggorf (A) is behind Chumimi (A) on the left hand side at (G-7).' },
                { 'Chemioue (A) is just South of Chumimi (A), take first left. (G-7).' },
                { 'Tapoh Lihzeh (A) is on the top side of the rock at the (G-6)/(G-7) border.' },
            } },
            { 'Each NPC will give you two facts about a fiend (described below). You must then report them to Chumimi (A).' },
            { 'Answer them both correctly and Chumimi (A) will respond "The information you\'ve provided corroborates with my own research perfectly! I appreciate your efforts. I must get working on my report, but please take this as a token of my thanks!". You will be rewarded 250 (500 Cruor first time) and a possible job seal.' },
            { 'Answer incorrectly and Chumimi (A) will respond "The information you\'ve provided seems reasonable enough. I appreciate your efforts. I must get working on my report, but please take this as a token of my thanks!". 200 Cruor is rewarded and NO Seal.' },
        },
    },
    ['Slip Slidin\' Away'] = {
        title             = 'Slip Slidin\' Away',
        starting_npc      = 'Michilca (A), Abyssea - Uleguerand',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'The Resistance seeks to send a strike team into the bowels of Thousandfall Ridge, a confirmed breeding pit for the hordes. Help keep Michilca\'s men on course as they execute their hazardous approach.',
        required_fame     = 'Abyssea - Uleguerand Fame Level: 2',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'Resilient Mantle  Chance at one of the following Empyrean Armor +1 Hands seals: Aoidos\' Seal: Hands Estoqueur\'s Seal: Hands Raider\'s Seal: Hands Savant\'s Seal: Hands',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Michilca (A) is at the base camp. Talk to her to begin.' },
            { 'Head to Conflux #7, and continue south past the Surveyors.' },
            { 'Head towards the western cliff near the gears.' },
            { 'You must start falling down the cliff at approximately 1/3 of the distance from the north wall and begin falling down.', sub = {
                { 'Zoom your camera completely out, then angle it downwards and left or right to see as far down the cliff as possible. You want to aim for the very small dip in the terrain, as just below that is the hole you must fall into.' },
                { 'If you "run backwards" up the cliff while you are sliding it slightly helps slow you down so you can hit the spot.' },
            } },
            { 'After meeting your mark, you need to speak to Perfaumand (A) right inside the entrance.' },
