    ['Ward Warden I (Attohwa)'] = {
        title             = 'Ward Warden I (Attohwa)',
        starting_npc      = 'Resistance Sapper (Attohwa) (F-9), Abyssea - Attohwa',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'It is imperative that the pulse martello and the clone wards are kept in prime condition. This operation requires you to transport the necessary repair materials from the stockpile, using the enchanted sack provided. Be mindful that the sack does not rupture in the process.',
        required_fame     = 'Abyssea - Attohwa Fame Level: 1',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = 'Varying amount of Cruor (Max: 1,000) and Resistance Credits (Max: 70) 0~1 of: any Empyrean Armor +1 Head seal',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to the Resistance Sapper (Attohwa) at (F-9) (Veridical Conflux #00) and to begin the quest.', sub = {
                { 'You will receive Key Item Magicked hempen sack.' },
                { 'This sack will disappear when you zone or log out only if it is filled first!.' },
            } },
            { 'Travel to the Target marked on your map.', sub = {
                { 'Quickest way to the target: Warp to Veridical Conflux #06. Head west across the bridge and past the incorrect crates. Go through then tunnel and hug the right wall. Eventually you will exit to Skeletons. You will need sneak here. Continue hugging the right wall until you get to hounds. Watch for the true sound NM Gieremund and avoid it. Continue hugging the right wall to re-enter through a crack past the hounds. Eventually you will get to another outdoor area with a rock bridge. You will walk back into another nook at (G-6) and you will find the correct crates. Backtrack to Veridical Conflux #06 by now hugging the left wall. Remember that you cannot warp or you will lose the key item.' },
            } },
            { 'Select the small Repair Trunk and fill your bag.', sub = {
                { 'There are three types of materials: pointy, jagged, and round. The more you pack, the more rewards you get, but if you pack too much it will tear and you will fail the quest. The former puts a heavier burden on the bag, so it\'s a good idea to start with the pointy ones, and if the message changes, lower the rank of the materials. The size of the bag is random to some extent, and the same packing method does not always give the same result. It\'s safe to start with the pointy material, switch to the round material when the message changes, and stop there when you\'re told, "It\'s about to reach the limit." or "squeaking under the tension."' },
            } },
            { 'Return to the Resistance Sapper (Attohwa) to complete the quest.' },
        },
    },
