    ['Water of Life'] = {
        title             = 'Water of Life',
        starting_npc      = 'Miageau (A) (L-11), Abyssea - La Theine',
        subtitle          = 'None',
        repeatable        = 'Yes',
        description       = 'La Theine\'s water sources have been found to be contaminated! Miageau has entrusted you with vials of purification agent to cleanse each of the plateau\'s four ponds.',
        required_fame     = 'Abyssea - La Theine Fame Level: 4',
        level_restriction = 'None',
        pack              = 'Abyssea',
        rewards           = '360 Cruor Evolith with random stats',
        previous_quest    = 'None',
        next_quest        = 'None',
        walkthrough       = {
            { 'Speak to Miageau (A) at (L-11), Veridical Conflux #06, to begin the quest.' },
            { 'You will receive the following four key items:', sub = {
                { 'Key Item Vial of purification agent (blk.)' },
                { 'Key Item Vial of purification agent (brz.)' },
                { 'Key Item Vial of purification agent (slv.)' },
                { 'Key Item Vial of purification agent (gld.).' },
            } },
            { 'Examine the 4 Murky Pond targetable locations in Abyssea - La Theine at (L-10), (K-11), and 2 at (H-7). These are the bodies of water you can see on your map.', sub = {
                { 'With each pond examined, your key items will be replaced with:', sub = {
                    { 'Key Item Black-labeled vial' },
