    ['Children of the Rune'] = {
        title             = 'Children of the Rune',
        starting_npc      = 'Octavien, South down the ramp from the Sverdhried Hillock waypoint at Eastern Adoulin (I-8)',
        subtitle          = 'Runic Engraver',
        repeatable        = 'No',
        description       = 'Years of excruciating training and long hours of study await those who desire to master the runic arts. One may circumvent this laborious process, however, by engraving runes upon his body with ink from a Yahse wildflower petal.',
        required_fame     = 'Adoulin Fame Level: 1',
        level_restriction = 'Level 30+',
        pack              = 'Seekers of Adoulin',
        rewards           = 'Sowilo Claymore Ability to become a Rune Fencer.',
        previous_quest    = 'None',
        next_quest        = 'Endeavoring to Awaken (Trial) Rune Fencing the Night Away',
        walkthrough       = {
            { 'Speak with Octavien at (I-8), accessed via the stairs.' },
            { 'Obtain a Yahse wildflower petal from Yahse Hunting Grounds at (K-7) by examining the Yahse Wildflower.', sub = {
                { 'The Yahse Wildflower is found on the northern of the three beaches.' },
            } },
            { 'Speak with Octavien again and attempt to "Use Rune Enhancement."', sub = {
                { 'The amount of attempts required can be from anywhere between 1 and 100, but it does not appear that you can fail.', sub = {
                    { 'Every 10th failure, he will remark on your progress:' },
                    { '10th fail: "I sense an ominous force interfering with your progress... Could it be the <your current job> within you?!"' },
                    { '20th fail: "Your 20th attempt and we\'re still no closer than before? Perhaps \'tis I who needs to train more, so I don\'t accidentally give the talentless dreams they can never accomplish."' },
                    { '30th fail: "I was under the impression that you were an adventurer renowned throughout the Middle Lands. Apparently that appellation amounts to little more than kindling for the fires of one\'s boasting."' },
                    { '40th fail: "...My condolences, sir/madame."' },
                    { '50th fail: "Why don\'t you quit while you still have your health? Many people would commit atrocities for a body as hale and hearty as yours."' },
                    { '60th fail: "Let me say this one thing: you may think you\'re special, but you\'re just as special as everyone else...that is to say, not at all."' },
                    { '70th fail: "I lost hope for you long ago, but this is already your 70th time. Any further attempts would be a waste of time for us both."' },
                    { '80th fail: "Zzz..."' },
                    { '90th fail: "I\'ve had enough of your incompetence! Let me spell this out loud and clear: y-o-u c-a-n-n-o-t u-s-e r-u-n-e-s!"' },
                    { '99th fail: "I might as well stick around to see if you can make it an even 100."' },
                } },
            } },
            { 'When you succeed, you will be rewarded with access to the Rune Fencer job and a Sowilo Claymore!' },
        },
    },
    ['Dances with Luopans'] = {
        title             = 'Dances with Luopans',
        starting_npc      = 'Sylvie, Western Adoulin (I-5)',
        subtitle          = 'Geodancer',
        repeatable        = 'No',
        description       = 'The intricacies of a geomancer lie in the luopans--compatriots in the casting of advanced magics. To make one, you need one petrified log and a fistful of homeland soil. Now where could you find them...?',
        required_fame     = 'Adoulin Fame Level: 1',
        level_restriction = 'Level 30+',
        pack              = 'Seekers of Adoulin',
        requirements      = 'Petrified Log',
        rewards           = 'Indi-Poison (Scroll) Matre Bell Ability to become a Geomancer',
        previous_quest    = 'None',
        next_quest        = 'Elementary, My Dear Sylvie',
        walkthrough       = {
            { 'Speak to Sylvie at Western Adoulin Waterfront (I-5) Waypoint #9.' },
            { 'Venture to the crag closest to your home nation and click the Ergon Locus ??? located beneath the stairs leading up to the Telepoint to obtain a Key Item Fistful of homeland soil.', sub = {
                { 'San d\'Oria - La Theine Plateau (K-8)' },
                { 'Bastok - Konschtat Highlands' },
                { 'Windurst - Tahrongi Canyon (I-6)' },
            } },
            { 'Return to Sylvie with the soil and trade her a Petrified Log to receive the Key Item Luopan.' },
            { 'Proceed to one of following Ergon Locus:', sub = {
                { 'Flourishing Island - Ceizak Battlegrounds (K-10, Frontier Station)' },
                { 'Bud of the Swarm - Ceizak Battlegrounds (I-8, Bivouac #2)' },
                { 'Immutable Boulder - Yahse Hunting Grounds (F-6, Bivouac #2)' },
            } },
            { 'Upon arriving at one of the locations above, you will receive a message stating that "You are assaulted by an uncanny sensation."', sub = {
                { 'Use the rest (/heal) command to begin charging your Key Item Luopan.' },
            } },
            { 'It can take up to 8 minutes of resting to gain enough of the lifestream to warm your Key Item Luopan.', sub = {
                { 'Once you have gathered enough energy, you will receive a message saying "You feel a mystical warmth welling up inside you!"' },
            } },
            { 'After receiving this message, return to Sylvie to complete the quest.' },
        },
    },
    ['Destiny\'s Device'] = {
        title             = 'Destiny\'s Device',
        starting_npc      = 'Octavien, Eastern Adoulin (I-8)',
        subtitle          = 'Ultimate Runeist',
        repeatable        = 'No',
        description       = 'Unearth the truth behind the ultimate trial so the Order of Orvail can avoid any more tragedies such as the one that took place two years prior.',
        required_fame     = 'Adoulin Fame Level: Unknown',
        level_restriction = 'None',
        pack              = 'None',
        rewards           = 'Runeist Coat',
        previous_quest    = 'Legacies Lost and Found',
        next_quest        = 'Rune Fencer Relic Armor Quiescence',
        walkthrough       = {
            { 'Speak to Octavien at Eastern Adoulin (I-8) while on Rune Fencer, He will give you the Key Item Runic kinegraver.' },
            { 'Speak to Gaddiux at the Inventors\' Coalition (Western Adoulin (J-10)), selecting the option referencing Adoulinian Kelp.', sub = {
                { 'Next, Pick the top 2 options. (Ask if the rune stone is still there) and (The trial objectives.) until he mention the Yahse wildflower petal.' },
            } },
            { 'Click the Yahse Wildflower in Yahse Hunting Grounds at (K-7) to receive a Yahse wildflower petal.' },
            { 'In Marjami Ravine, travel to the ??? at the base of the waterfall east of Bivouac #2 at (I-8). Use Ignis three times, and then interact with the ??? for a cutscene and a Key Item Vial of vivid rainbow extract.', sub = {
                { 'If you get stuck and don\'t get the cutscene return to Gaddiux and repeat the above until he tells you to first get a Yahse Wildflower petal and then head to Marjami.' },
            } },
            { 'Speak to Gaddiux once more, again selecting the option referencing Adoulinian Kelp, for another cutscene.' },
            { 'Speak to Octavien.' },
            { 'Travel to the secret beach at (J-11) in Foret de Hennetiel (south of Bivouac #2) and examine the Bloodstained Glove on the shoreline for a cutscene.' },
            { 'After all party members have watched the cutscene, click the Bloodstained Glove once more to spawn Insidio. This cutscene and fight can be done as any job, and Trusts are usable.', sub = {
                { 'Insidio is an Orobon NM which notably has access to Mayhem Lantern (AoE Charm).', sub = {
                    { 'Upon each usage of Mayhem Lantern, Insidio will gain a significant reduction to physical damage taken until it takes nearly no physical damage.' },
                } },
                { 'Party members actively participating in the quest will receive a Insidio\'s extinguished lantern upon defeat. Other members who are assisting will receive up to 10,000 Bayld (depending on the size of the party), if they have never assisted in this battle before.' },
                { 'Strategy for Insidio - If attempting to solo this fight, the easiest way to do so is to summon your trusts, preferably those that can deal magic damage, your best dps, and those that can Skillchain. Now pop Insidio and let your trusts get hate. Once they\'ve gained a decent amount of hate, move well out of range of charm AoE. Alternatively use Tenebrae with Pflug and other Magic Evasion buffs. Now sit back and watch your trusts do all the work. Using this strategy with ilvl 119 gear trusts easily took down NM within 8-10 minutes.' },
            } },
            { '(Optional) Examine the Bloodstained Glove after defeating Insidio.' },
            { 'Return to Octavien to complete the quest and receive your reward.' },
            { '(Optional) Talk to Zurko-Bazurko in Mhaura at the proto-waypoint for an additional cutscene. He will ask you to give him the runic kinegraver.' },
        },
    },
    ['Did You Feel That?'] = {
        title             = 'Did You Feel That?',
        starting_npc      = 'Udip Ferawoh, Marjami Ravine',
        subtitle          = 'None',
        repeatable        = 'No',
        description       = 'Velkk have been planting spinescent protuberances all throughout the ravine, and Udip Ferawoh is sick of it. She wants you to suffer five amnesic attacks from them before returning--but don\'t get in over your head.',
